    { template_id = "tusked_ursian", name = "tusked ursian", level = 37, spawn_areas = { "Gyldemar Forest" }, roam_areas = { "Gyldemar Forest" }, family = "bear", body_type = "quadruped", hp = 260, hp_variance = 26, ds_melee = 139, ds_ranged = 127, td = 142, armor_asg = 12, armor_natural = true, preferred_stance = "offensive", stance_profile = "skirmisher", description = "Standing nearly nine feet in height, the tusked ursian appears to be an unnatural union between a boar and a bear. Her yellow-tusked maw is lined with jagged fangs and beady eyes peer over a moist snout. Powerful limbs ending in black-nailed claws attest to the ferocity of this beast.", attacks = { { type = "claw" }, { type = "charge_attack" }, { type = "bite" } }, abilities = { "charge_knockdown" } },

