    { template_id = "mud_wasp", name = "mud wasp", level = 38, spawn_areas = { "Fhorian Village" }, roam_areas = { "Fhorian Village" }, family = "wasp", body_type = "insectoid", hp = 260, hp_variance = 26, td = 174, armor_asg = 8, armor_natural = true, preferred_stance = "offensive", stance_profile = "skirmisher", description = "With a body about the size of a human hand, and a wingspan approaching a foot, the mud wasp is a rather intimidating sight. It is a superb example of camouflage, with a brown body covered in splatters of mud, and eyes the color of muddy water. The wings are the only exception to the brown color scheme, being transparent with a faint touch of blue.", attacks = { { type = "stinger_attack" } } },
    { template_id = "shadow_steed", base_template = "shadow_mare", name = "shadow steed", level = 38, spawn_areas = { "Shadow Valley" }, roam_areas = { "Shadow Valley" }, family = "equine", classification = "non_corporeal_undead", body_type = "quadruped", hp = 400, hp_variance = 40, preferred_stance = "offensive", stance_profile = "skirmisher", description = "As magnificent as any living horse, this shadow steed stares beyond you with glowing red eyes. Its matte black coat provides a sharp contrast to its shining silvery tail and mane. The shadow steed paws the ground restlessly with its front hooves as it swishes its tail, flickering into and out of the shadows." },
    { template_id = "vesperti", name = "vesperti", level = 38, spawn_areas = { "Foggy Valley" }, roam_areas = { "Foggy Valley" }, family = "vesperti", body_type = "biped", hp = 240, hp_variance = 24, armor_asg = 6, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "The vesperti stands roughly six feet tall, with coarse black fur covering his willowy frame. A veined membrane of skin extends from his ankle up to his wrists, edges scalloped like those of a bat's wings. Capping off the wings are taloned hands and feet, the long, tapered digits bearing glossy black claws. Intense eyes stare out from beneath a mane of tousled hair, looking far too sentient for any measure of comfort.", attacks = { { type = "flail" }, { type = "whip" }, { type = "scimitar" } }, spells = { "Energy Maelstrom", "Pain", "Curse", "Pestilence", "Mana Drain" } },

    -- Level 39
