    { template_id = "stone_gargoyle", base_template = "lesser_stone_gargoyle", name = "stone gargoyle", level = 39, spawn_areas = { "Darkstone Castle" }, roam_areas = { "Darkstone Castle" }, family = "gargoyle", body_type = "biped", ds_melee = 116, td = 117, preferred_stance = "guarded", stance_profile = "skirmisher", description = "The stone gargoyle, an animated being, was once a huge, grey, granite carving that overlooked the castle walls. Standing over fifteen feet tall on its powerful hind legs, the stone gargoyle was sculpted with a body similar to a lion's and a head that is a grotesque union between a human and a bat. Long horns protrude from the forehead and needle-like fangs extend menacingly below the upper lip. Swirling, yellow-green eyes, the only non-rock portion of the beast's anatomy, coldly examine the surrounding area.", attacks = { { type = "bite" }, { type = "claw" } } },
    { template_id = "vourkha", name = "vourkha", level = 39, spawn_areas = { "Black Moor" }, roam_areas = { "Black Moor" }, family = "wraith", classification = "corporeal_undead", body_type = "biped", hp = 240, hp_variance = 24, ds_melee = 243, ds_bolt = 163, td = 163, udf = 195, armor_asg = 7, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "Empty black soulless eyes gaze from the gaunt, grey form of the wraithlike vourkha. His thin-lipped mouth gaped in a silent howl, he grasps at the fetid air with gnarled, clawed hands as he glides just above the ground, trailing tendrils of thick white ectoplasm that seem to seep from his shredded clothing. The creature seems to fade in and out of corporeal existence as if he walked in an eternal patch of shadow.", attacks = { { type = "bite" }, { type = "claw" } }, abilities = { "acid_spray", "fire_bolt", "elemental_bias_508" } },

