    { template_id = "forest_bendith", name = "forest bendith", level = 40, spawn_areas = { "Gyldemar Forest" }, roam_areas = { "Gyldemar Forest" }, family = "fey", body_type = "biped", hp = 400, hp_variance = 40, ds_melee = 156, td = 167, armor_asg = 12, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "Short and stumpy with pale yellowish skin, the forest bendith is hunched and her body is covered with greenish mosses of varying thickness. Imbedded into the soft flesh of her bulbous head are a pair of watery purple eyes which peer forth with a sense of malignant inquisitiveness. An odor of damp mold and rotting vegetation seems to hang about the diminutive being.", attacks = { { type = "scimitar" }, { type = "morning_star" } }, abilities = { "hide" } },
    { template_id = "kiramon_worker", name = "kiramon worker", level = 40, spawn_areas = { "Kharam Dzu", "Seethe Naedal", "Darkstone Castle", "Czeroth Labyrinth" }, roam_areas = { "Kharam Dzu", "Seethe Naedal", "Darkstone Castle", "Czeroth Labyrinth" }, family = "kiramon", body_type = "insectoid", hp = 300, hp_variance = 30, ds_melee = 169, ds_bolt = 170, td = 164, udf = 209, armor_asg = 12, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "The kiramon worker has a mobile head with huge, bulging, eyes that sparkle in a faceted clustering around a lidless perimeter. Protruding from its massive head is a vicious-looking snout with insectile mandibles, while the back of the cranium is a distended, two-lobed case. Remarkably powerful rear legs jut backward from an extremely hard, resilient exoskeleton that seems to be in constant motion. Though its middle legs have evolved away long ago, the front legs end in strong opposing claws and knobby-jointed fingers. Stunted wings flap uselessly from its long cylindrical body.", attacks = { { type = "claw" }, { type = "charge_attack" } }, spells = { "Disease" }, abilities = { "powerful_blow" } },
    { template_id = "spectral_miner", name = "spectral miner", level = 40, spawn_areas = { "Shadow Valley" }, roam_areas = { "Shadow Valley" }, family = "ghost", classification = "non_corporeal_undead", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 183, ds_bolt = 187, td = 166, armor_asg = 7, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "This somewhat orc-like looking humanoid creature is surrounded with an eerie white glow and appears to be transparent. An abundance of excessively wrinkled skin and long bushy grey eyebrows serve to make spectral miner appear ancient.", abilities = { "spirit_warding_i_101", "spirit_defense_103", "spirit_shield_202" } },
    { template_id = "writhing_frost_glazed_vine", base_template = "blackened_decaying_tumbleweed", name = "writhing frost-glazed vine", level = 40, spawn_areas = { "Frozen Bramble" }, roam_areas = { "Frozen Bramble" }, family = "plant", classification = "corporeal_undead", body_type = "hybrid", td = 170, preferred_stance = "forward", stance_profile = "berserker", description = "This \"little\" vine seems to be a bit on the feeling poorly side but if it catches you, likely you'll feel pretty bad too." },

