    { template_id = "lesser_ice_giant", base_template = "frost_giant", name = "lesser ice giant", level = 41, spawn_areas = { "Olbin Pass" }, roam_areas = { "Olbin Pass" }, family = "giant", body_type = "biped", ds_melee = 236, ds_bolt = 218, td = 165, udf = 239, preferred_stance = "forward", stance_profile = "berserker", description = "Standing twice as tall as the tallest giantman, the ice giant trails frost and snow in her wake. Seemingly carved from living ice and snow, icy blue eyes set beneath a heavily furrowed brow and a tangled mop of icy blue hair provide a splash of color against the ice giant's dull white frost-covered skin.", attacks = { { type = "massive_icicle" } } },
    { template_id = "roater", name = "roa'ter", level = 41, spawn_areas = { "Castle Varunar", "Darkstone Castle", "Czeroth Labyrinth" }, roam_areas = { "Castle Varunar", "Darkstone Castle", "Czeroth Labyrinth" }, family = "worm", body_type = "ophidian", hp = 260, hp_variance = 26, ds_melee = 141, ds_bolt = 143, td = 162, armor_asg = 12, armor_natural = true, preferred_stance = "offensive", stance_profile = "skirmisher", description = "This massive worm is probably over twenty to thirty feet long, making it an easy target to hit, but having incomparable force and strength. Dark red in color, it seems to have no eyes, but its keen sense of smell quickly finds targets.", attacks = { { type = "charge" } }, abilities = { "hide" } },
    { template_id = "sheruvian_monk", base_template = "deranged_sentry", name = "sheruvian monk", level = 41, spawn_areas = { "The Broken Lands" }, roam_areas = { "The Broken Lands" }, family = "humanoid", body_type = "biped", ds_melee = 265, ds_bolt = 260, td = 231, preferred_stance = "forward", stance_profile = "berserker", description = "It is hard to tell if the Sheruvian monk is human, or some foul spawn of inhuman parents. The head of the warrior-monk has been shaved smooth and is covered in dark, mystic runes tattooed on its scalp. A heavy brow hangs low over its cold, calculating eyes.", attacks = { { type = "jeddart_axe" } }, abilities = { "healing_minor" } },
    { template_id = "skeletal_lord", name = "skeletal lord", level = 41, spawn_areas = { "Castle Varunar" }, roam_areas = { "Castle Varunar" }, family = "humanoid", classification = "corporeal_undead", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 226, ds_ranged = 200, ds_bolt = 200, td = 138, udf = 244, armor_asg = 13, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "The skeletal lord still stands proudly erect. Skilled in the art of battle, it takes its time, carefully measuring each powerful attack to strike at the enemy's most exposed point. Its body reduced to shreds of flesh, eye sockets now empty, the skeletal lord still attacks with amazing accuracy.", attacks = { { type = "lance" } }, abilities = { "disarm_weapon", "trip" } },

    -- Level 42
    { template_id = "baesrukha", name = "baesrukha", level = 42, spawn_areas = { "Black Moor" }, roam_areas = { "Black Moor" }, family = "humanoid", classification = "corporeal_undead", body_type = "biped", hp = 240, hp_variance = 24, ds_bolt = 159, td = 188, armor_asg = 8, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "Her emaciated form roughly humanoid, the baesrukha glides along the ground, clawing at the air with bloodied talons. Her burning red eyes stare malevolently at any intruder, gazing out from a nearly featureless face above a fanged, lipless mouth. Whitish tendrils of ectoplasm coil and whip around her tattered robes, writhing in the miasma that surrounds the ancient wraithlike creature like hungry snakes.", attacks = { { type = "claw" }, { type = "bite" } }, spells = { "Cold Snap", "Elemental Blast" }, abilities = { "fire_bolt", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_bias_508" } },
    { template_id = "dark_vortece", name = "dark vortece", level = 42, spawn_areas = { "The Broken Lands" }, roam_areas = { "The Broken Lands" }, family = "vortece", classification = "magical", body_type = "hybrid", hp = 300, hp_variance = 30, ds_melee = 28, td = 159, preferred_stance = "guarded", stance_profile = "caster", description = "The 'dark vortece' is a mass of dark, swirling shadows. Little more is known about this deadly creature despite many attempts to study their origins. This is understandable when you consider the one well known fact about them: Simply being in the presense of a dark vortece is enough to endanger your life, due to their tendency to drain the life out of everything around them.", spells = { "Unknown" } },
    { template_id = "frozen_corpse", base_template = "greater_fetid_corpse", name = "frozen corpse", level = 42, spawn_areas = { "Arctic Tundra", "Nightmare Gorge" }, roam_areas = { "Arctic Tundra", "Nightmare Gorge" }, family = "zombie", classification = "corporeal_undead", body_type = "biped", ds_bolt = 244, td = 168, preferred_stance = "forward", stance_profile = "berserker", description = "Unearthed from his place of resting by the avalanches, the frozen corpse stiffly roams the ice fields looking for rest again. Ranging from dwarf to giantman in size, the frozen corpse attacks ruthlessly any living thing in his path, perhaps blaming the living for his current predicament. His features are taut and drawn, but most of the flesh is still intact, preserved by the subzero cold. His movements are punctuated by the loud screeching of ice against ice in his joints and a continual crackling as his frozen appendages fracture.", attacks = { { type = "ice_pick" } } },
    { template_id = "minor_glacei", base_template = "dark_vortece", name = "minor glacei", level = 42, spawn_areas = { "Arctic Tundra", "Nightmare Gorge" }, roam_areas = { "Arctic Tundra", "Nightmare Gorge" }, family = "elemental", classification = "magical", body_type = "hybrid", ds_melee = 223, td = 158, preferred_stance = "forward", stance_profile = "berserker", description = "The minor glacei is a conglomeration of ice and snow that writhes and moves with a mind of its own formed in a vaguely humanoid shape. The cold generated by the minor glacei is nearly unbearable.", attacks = { { type = "lash" }, { type = "strike" } } },
    { template_id = "phantasma", name = "phantasma", level = 42, spawn_areas = { "Castle Varunar" }, roam_areas = { "Castle Varunar" }, family = "ghost", classification = "non_corporeal_undead", body_type = "biped", hp = 240, hp_variance = 24, ds_melee = 228, ds_ranged = 216, ds_bolt = 222, td = 185, armor_asg = 5, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "A barely visible spirit, the phantasma floats silently across the room. Its bald head, thick neck, muscular forearms and fixed sneer reflect its former positions of jailer and torturer. Rotting leather armor drapes the phantasma, providing it with its only solid link to the living past.", attacks = { { type = "leather_whip" } }, spells = { "Corrupt Essence", "Disintegrate", "Pain", "Curse" }, abilities = { "spirit_warding_i_101", "spirit_defense_103", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414" } },
    { template_id = "shan_cleric", name = "shan cleric", level = 42, spawn_areas = { "Foggy Valley" }, roam_areas = { "Foggy Valley" }, family = "shan", body_type = "biped", hp = 240, hp_variance = 24, ds_melee = 280, td = 182, armor_asg = 8, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "The shan cleric stands in a half-crouch, her long, knotty legs giving her that lanky, dangerous look of a wolf. Walking upright, the body covered with mottled grey fur and her long arms conclude in large, clawed hands with semi-opposable thumbs. The shan cleric's dog-like visage is fierce, with slavering jaws and eyes that glow like something out of a bad dream.", attacks = { { type = "morning_star" } }, spells = { "Bind" }, abilities = { "spirit_strike", "lesser_shroud_120", "spirit_defense_103", "spirit_warding_i_101" } },
    { template_id = "shan_ranger", name = "shan ranger", level = 42, spawn_areas = { "Foggy Valley" }, roam_areas = { "Foggy Valley" }, family = "shan", body_type = "biped", hp = 240, hp_variance = 24, td = 165, armor_asg = 11, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "The shan ranger stands in a half-crouch, his long, knotty legs giving him that lanky, dangerous look of a wolf. Walking upright, the body covered with mottled grey fur and his long arms conclude in large, clawed hands with semi-opposable thumbs. The shan ranger's dog-like visage is fierce, with slavering jaws and eyes that glow like something out of a bad dream.", attacks = { { type = "longsword" } }, spells = { "Wild Entropy", "Phoen's Strength" }, abilities = { "web_immobilize", "spirit_strike", "tail_spike_volley", "entangle", "sonic_wail", "gas_cloud", "mobility_618", "natural_colors_601", "self_control_613", "spirit_warding_i_101", "spirit_defense_103" } },
    { template_id = "shan_warrior", name = "shan warrior", level = 42, spawn_areas = { "Foggy Valley" }, roam_areas = { "Foggy Valley" }, family = "shan", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 216, td = 150, preferred_stance = "forward", stance_profile = "berserker", description = "The shan warrior stands in a half-crouch, her long, knotty legs giving her that lanky, dangerous look of a wolf. Walking upright, the body covered with mottled grey fur and her long arms conclude in large, clawed hands with semi-opposable thumbs. The shan warrior's dog-like visage is fierce, with slavering jaws and eyes that glow like something out of a bad dream.", attacks = { { type = "flamberge" }, { type = "longsword" }, { type = "jeddart_axe" } }, abilities = { "disarm_weapon" } },
    { template_id = "shan_wizard", base_template = "grutik_shaman", name = "shan wizard", level = 42, spawn_areas = { "Foggy Valley" }, roam_areas = { "Foggy Valley" }, family = "shan", body_type = "biped", td = 170, preferred_stance = "guarded", stance_profile = "caster", description = "The shan wizard stands in a half-crouch, his long, knotty legs giving him that lanky, dangerous look of a wolf. Walking upright, the body covered with mottled grey fur and his long arms conclude in large, clawed hands with semi-opposable thumbs. The shan wizard's dog-like visage is fierce, with slavering jaws and eyes that glow like something out of a bad dream.", attacks = { { type = "dagger" } }, spells = { "Elemental Focus" }, abilities = { "acid_spray", "earthen_fury_caster", "elemental_targeting_425", "elemental_defense_ii_406", "elemental_defense_iii_414" } },

    -- Level 43
    { template_id = "dreadnought_raptor", name = "dreadnought raptor", level = 43, spawn_areas = { "Gyldemar Green" }, roam_areas = { "Gyldemar Green" }, family = "bird", body_type = "avian", hp = 260, hp_variance = 26, ds_melee = 197, td = 153, udf = 240, armor_asg = 8, armor_natural = true, preferred_stance = "offensive", stance_profile = "skirmisher", description = "The dreadnought raptor is a large, distinctly marked bird, with a wingspan twice the height of a giantman. Glossy black feathers and white markings on its broad wings and rounded tail give the raptor an ominous appearance, and feathers cover its legs to its feet. A dark ruff borders the dreadnought raptor's bald red head and neck. Its hooked bill and powerful talons are well suited for hunting.", attacks = { { type = "impale" }, { type = "bite" }, { type = "claw" } }, abilities = { "powerful_blow" } },
    { template_id = "night_mare", base_template = "skeletal_warhorse", name = "night mare", level = 43, spawn_areas = { "Shadow Valley" }, roam_areas = { "Shadow Valley" }, family = "equine", classification = "corporeal_undead", body_type = "quadruped", hp = 400, hp_variance = 40, preferred_stance = "offensive", stance_profile = "skirmisher", description = "Eyes glowing green with the hatred of the dead, the night mare's stare bores right through you. A magnificently beautiful equine, the night mare seems to be bathed in a deep green glow that tosses roiling shadows across her coat. Upon closer inspection, shadows can be seen that roil and crawl across its coat much like the nightmares that keep many awake at night. It is said that gazing upon a nightmare for too long will induce waking nightmares that are difficult to shake off." },
    { template_id = "wasp_nest", base_template = "mud_wasp", name = "wasp nest", level = 43, spawn_areas = { "Fhorian Village", "Lava Flows" }, roam_areas = { "Fhorian Village", "Lava Flows" }, family = "wasp", body_type = "insectoid", td = 72, preferred_stance = "offensive", stance_profile = "skirmisher", description = "Smooth black basalt forms a squat cone, taller than many giantmen. The rock looks almost to have been molded or poured into shape, lacking any sign of having been worked. The top is apparently open, allowing the wasps access to the interior. A deep hum radiates from the nest, implying a feverish level of activity inside." },

    -- Level 44
    { template_id = "forest_trali", name = "forest trali", level = 44, spawn_areas = { "Gyldemar Green" }, roam_areas = { "Gyldemar Green" }, family = "trali", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 199, td = 168, udf = 230, armor_asg = 9, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "Standing nearly six feet tall, the man-like forest trali watches adventurers' every move with piercing grey eyes. A short matted, reddish grey mane covers her head and her skin has a greenish grey hue. There is little doubt that the stealthy forest trali can be a formidable opponent when need arises, or when she is hard pressed.", attacks = { { type = "broadsword" }, { type = "dart" } } },
    { template_id = "mastodonic_leopard", name = "mastodonic leopard", level = 44, spawn_areas = { "Gyldemar Green" }, roam_areas = { "Gyldemar Green" }, family = "feline", body_type = "quadruped", hp = 400, hp_variance = 40, ds_melee = 189, ds_ranged = 211, td = 166, udf = 233, armor_asg = 10, armor_natural = true, preferred_stance = "offensive", stance_profile = "skirmisher", description = "The mastodonic leopard has a long, narrow body, relatively short muscular legs and large broad paws. His large, broad tail is used for balancing himself in the trees. Two alert yellow eyes gaze over his broad snout, capped on the leopard's narrow head by his tufted ears. Most striking are his markings: six large, narrow, brown blotches, edged in black, with pale areas separating the blotches on his sides. Along his back, the leopard has a series of large open-centered spots, and his underside is solidly pale. The mastodonic leopard's square jaw and extra long canine teeth, characteristic of the northern sabre-toothed tiger, are ideal for shredding meat.", attacks = { { type = "bite" }, { type = "claw" } } },
    { template_id = "polar_bear", name = "polar bear", level = 44, spawn_areas = { "Arctic Tundra" }, roam_areas = { "Arctic Tundra" }, family = "bear", body_type = "quadruped", hp = 400, hp_variance = 40, ds_melee = 273, ds_bolt = 226, td = 167, preferred_stance = "offensive", stance_profile = "skirmisher", description = "The polar bear is the largest of all bears, weighing in at close to 2000 pounds with an overall body length of around nine feet long. The bear has a distinctive all white coat, triangular profile, long neck, and small ears. The polar bear's nose, lips and all skin under his fur are black. This bear's front paws are very wide for paddling through arctic waters. Heavy fur, dense underfur, and thick layer of insulating fat allow the bear to maintain a normal body temperature when the outside temperature drops far below freezing.", attacks = { { type = "bite" }, { type = "charge" }, { type = "claw" } } },
    { template_id = "sheruvian_priest", name = "sheruvian priest", level = 44, spawn_areas = { "The Broken Lands" }, roam_areas = { "The Broken Lands" }, family = "humanoid", body_type = "biped", hp = 240, hp_variance = 24, td = 182, armor_asg = 2, armor_natural = false, preferred_stance = "guarded", stance_profile = "ranged", description = "Carrying an air of piety and grace, the Sheruvian priest is a figure of cold dedication to his deity. Undecipherable runes cover his shaved head and every other visible part of his body. His hands are soft, unused to manual labor or the rigors of combat, yet he is a dangerous foe when confronted. It is unusual to find the Sheruvian priest unaccompanied by his minions, as he prefers the halls of worship where he can perform his rituals undisturbed.", attacks = { { type = "runestaff" } } },
    { template_id = "sheruvian_warlock", name = "sheruvian warlock", level = 44, spawn_areas = { "The Broken Lands" }, roam_areas = { "The Broken Lands" }, family = "humanoid", body_type = "biped", hp = 240, hp_variance = 24, td = 182, armor_asg = 2, armor_natural = false, preferred_stance = "guarded", stance_profile = "ranged", description = "The Sheruvian warlock stands proudly, his coal black eyes scanning the room as a nobleman would haughtily survey his domain. His long, black hair courses wildly about his face and spills down over the upturned collar of his flaring cape. His taut lips twist into a malignant sneer and his eyes narrow suspiciously. Undecipherable runes, tattooed over his entire face, stand out starkly against his pale, white skin.", attacks = { { type = "runestaff" } } },

    -- Level 45
    { template_id = "dark_frosty_plant", name = "dark frosty plant", level = 45, spawn_areas = { "Frozen Bramble" }, roam_areas = { "Frozen Bramble" }, family = "plant", classification = "corporeal_undead", body_type = "hybrid", hp = 400, hp_variance = 40, td = 186, preferred_stance = "forward", stance_profile = "berserker", description = "Though this plant with its droopy leafs and sickly flowers is a bit on the far gone side, it might still benefit from being re-potted. Preferably six feet under!", attacks = { { type = "ranged_frosty_seed" }, { type = "ranged_frost_covered_crystalline_flower" }, { type = "melee_stab" } } },
    { template_id = "ice_wraith", base_template = "bog_wraith", name = "ice wraith", level = 45, spawn_areas = { "Nightmare Gorge", "Arctic Tundra" }, roam_areas = { "Nightmare Gorge", "Arctic Tundra" }, family = "wraith", classification = "non_corporeal_undead", body_type = "biped", hp = 240, hp_variance = 24, preferred_stance = "forward", stance_profile = "berserker", description = "Glistening from head to toe with brilliant clear ice, the ice wraith is a picture of deadly beauty. Long, razor-sharp shards of ice form his claws, and two thin ice stalactites serve as fangs. When illuminated by the sun, the crystalline ice wraith reflects all colors of the rainbow, often mesmerizing his prey, then striking with potent magic." },
    { template_id = "lesser_vruul", name = "lesser vruul", level = 45, spawn_areas = { "The Broken Lands" }, roam_areas = { "The Broken Lands" }, family = "vruul", classification = "corporeal_undead", body_type = "biped", hp = 240, hp_variance = 24, td = 198, preferred_stance = "guarded", stance_profile = "caster", description = "The lesser vruul has tough, leathery hide, as black as midnight. Bat-like wings sprout from its back, but they do not look large or strong enough to support its weight in flight. The vruul's claws are long, sharp and appear to be stained with the blood of many victims. Its eyes are eerie, solid green orbs that seem to glow with an inner power.", attacks = { { type = "battle_axe" }, { type = "short_sword" } }, spells = { "Bind", "Calm", "Frenzy", "Interference", "Silence", "Unbalance" }, abilities = { "bravery_211", "heroism_215", "lesser_shroud_120", "spell_shield_219", "spirit_defense_103", "spirit_shield_202", "spirit_warding_i_101" } },

    -- Level 46
    { template_id = "cinder_wasp", name = "cinder wasp", level = 46, spawn_areas = { "Lava Flows" }, roam_areas = { "Lava Flows" }, family = "wasp", body_type = "insectoid", hp = 260, hp_variance = 26, td = 235, udf = 273, armor_asg = 8, armor_natural = true, preferred_stance = "offensive", stance_profile = "skirmisher", description = "With a body length of nearly 1 foot, and a wingspan of 18 inches, a cinder wasp is without a doubt, the biggest wasp to be seen. The body is black with irridescent blue highlights. The wings are like soap bubbles, clear with rainbows of color shimmering across them. Large redly glowing compound eyes and a stinger large enough to make a nasty stiletto give this creature a distinctly threatening appearance.", attacks = { { type = "stinger_attack" } } },
    { template_id = "forest_trali_shaman", name = "forest trali shaman", level = 46, spawn_areas = { "Gyldemar Green" }, roam_areas = { "Gyldemar Green" }, family = "trali", body_type = "biped", hp = 240, hp_variance = 24, td = 198, armor_asg = 9, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "Standing nearly six feet tall, the man-like trali shaman watches adventurers' every move with piercing grey eyes. A short matted, reddish grey mane covers his head and his skin has a greenish grey hue. There is little doubt that the stealthy trali shaman can be a formidable opponent when need arises, or when he is hard pressed.", attacks = { { type = "mace" } }, spells = { "Bind", "Calm", "Silence", "Unbalance", "Phoen's Strength" }, abilities = { "spirit_strike", "tail_spike_volley", "natural_colors_601", "spirit_defense_103", "spirit_shield_202", "spell_shield_219", "spirit_warding_i_101" } },
    { template_id = "greater_ice_giant", name = "greater ice giant", level = 46, spawn_areas = { "Olbin Pass" }, roam_areas = { "Olbin Pass" }, family = "giant", body_type = "biped", hp = 400, hp_variance = 40, ds_melee = 156, ds_bolt = 183, td = 189, preferred_stance = "guarded", stance_profile = "caster", description = "Standing nearly three times as tall as a giantman, the ice giant trails frost and snow in his wake. Seemingly carved from living ice and snow, icy blue eyes set beneath a heavily furrowed brow and a tangled mop of icy blue hair provide a splash of color against the ice giant's dull white frost-covered skin.", attacks = { { type = "battle_axe" } }, spells = { "Spirit Dispel" }, abilities = { "cold_flare" } },
    { template_id = "kiramon_defender", name = "kiramon defender", level = 46, spawn_areas = { "Darkstone Castle", "Kharam Dzu", "Seethe Naedal", "Czeroth Labyrinth" }, roam_areas = { "Darkstone Castle", "Kharam Dzu", "Seethe Naedal", "Czeroth Labyrinth" }, family = "kiramon", body_type = "insectoid", hp = 300, hp_variance = 30, ds_melee = 188, ds_ranged = 205, ds_bolt = 195, td = 201, udf = 234, armor_asg = 12, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "The kiramon defender has a mobile head with huge, bulging, eyes that sparkle in a faceted clustering around a lidless perimeter. Protruding from his massive head is a vicious-looking snout with insectile mandibles, while the back of his cranium is a distended, two-lobed case. Remarkably powerful rear legs jut backward from an extremely hard, resilient exoskeleton that seems to be in constant motion. Though his middle legs have evolved away long ago, his front legs end in strong opposing claws and knobby-jointed fingers. Stunted wings flap uselessly from his long cylindrical body.", attacks = { { type = "tongue_strike" }, { type = "charge_attack" }, { type = "claw" } }, spells = { "Disease" }, abilities = { "hamstring", "powerful_blow" } },
    { template_id = "lesser_faeroth", name = "lesser faeroth", level = 46, spawn_areas = { "Gyldemar Forest" }, roam_areas = { "Gyldemar Forest" }, family = "faeroth", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 208, ds_ranged = 216, ds_bolt = 229, td = 175, armor_asg = 8, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "The 'lesser faeroth' looks as though she is a near relative to a monkey. Standing on powerful forelimbs, her body is lifted entirely off the ground. Two atrophied legs with filthy claws dangle loosely below the body and look to be double-jointed. A spark of malevolent intelligence burns in her eyes.", attacks = { { type = "bite" }, { type = "claw" }, { type = "pound" } } },

    -- Level 47
    { template_id = "major_glacei", name = "major glacei", level = 47, spawn_areas = { "Arctic Tundra", "Nightmare Gorge" }, roam_areas = { "Arctic Tundra", "Nightmare Gorge" }, family = "elemental", classification = "magical", body_type = "hybrid", hp = 240, hp_variance = 24, td = 211, preferred_stance = "forward", stance_profile = "berserker", description = "The major glacei is a conglomeration of ice and snow that writhes and moves with a mind of its own formed in a vaguely humanoid shape. The cold generated by the major glacei is nearly unbearable.", attacks = { { type = "lash" } }, abilities = { "cold_flare" } },

    -- Level 48
    { template_id = "dybbuk", name = "dybbuk", level = 48, spawn_areas = { "Bonespear Tower" }, roam_areas = { "Bonespear Tower" }, family = "chimeric", classification = "corporeal_undead", body_type = "hybrid", hp = 400, hp_variance = 40, ds_melee = 208, td = 196, preferred_stance = "forward", stance_profile = "berserker", description = "The dybbuk is a piecemeal composition of horror, its mismatched sections of body coalesced into a whole that would frighten a banshee. The thing lumbers, managing to look clumsy and menacing at the same time. The skin is pallid and stretched, and in places, gaping wounds reveal worse atrophy than that evident on the abomination's exterior. Huge hands grope before the dybbuk's trunk, sweeping around it in flailing arcs and leaving no doubt that close proximity to the creature spells dire results.", attacks = { { type = "length_of_rusted_chain" } } },
    { template_id = "horned_vortaz", name = "horned vor'taz", level = 48, spawn_areas = { "Gyldemar Forest" }, roam_areas = { "Gyldemar Forest" }, family = "vor_taz", classification = "magical", body_type = "biped", hp = 400, hp_variance = 40, ds_ranged = 165, ds_bolt = 202, td = 208, armor_asg = 12, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "His fanged mouth frothing and snapping at the air, the horned vor'taz glares about with hate-filled eyes. Greater than the size of a human, the frame of the vor'taz is covered in dull grey flesh which is spotted with wart-like bumps. Affixed to his heavily muscled neck, the bony skull of the vor'taz supports a cruel horn which slashes back and forth in a menacing fashion.", attacks = { { type = "charge" } }, spells = { "Sun Burst" }, abilities = { "gas_cloud", "sonic_wail", "spirit_strike", "entangle", "natural_colors_601", "self_control_613", "spirit_defense_103", "spirit_warding_i_101" } },
    { template_id = "large_thorned_shrub", base_template = "dybbuk", name = "large thorned shrub", level = 48, spawn_areas = { "Frozen Bramble" }, roam_areas = { "Frozen Bramble" }, family = "shrub", classification = "corporeal_undead", body_type = "hybrid", preferred_stance = "forward", stance_profile = "berserker", description = "Sometime when you are clearing shrubs from your property, think back on how much easier it is than when the shrub decides it should be you that gets cleared.", attacks = { { type = "small_glistening_thorn" } } },
    { template_id = "red_scaled_thrak", name = "red-scaled thrak", level = 48, spawn_areas = { "Lava Flows" }, roam_areas = { "Lava Flows" }, family = "reptilian", body_type = "quadruped", hp = 260, hp_variance = 26, td = 195, udf = 264, armor_asg = 12, armor_natural = true, preferred_stance = "offensive", stance_profile = "skirmisher", description = "A red-scaled thrak is nearly twice the size of its mundane relative, the common thrak. Armed with heavy claws on all four feet and a nasty set of long razor-sharp fangs, it appears rather well equipped for offense. Its skin has a rough pebbled texture, dark gray to black on the back, with a brilliant red underbelly and tail.", attacks = { { type = "bite_attack" }, { type = "claw_attack" } } },
    { template_id = "sand_devil", name = "sand devil", level = 48, spawn_areas = { "Fhorian Village" }, roam_areas = { "Fhorian Village" }, family = "reptilian", body_type = "quadruped", hp = 240, hp_variance = 24, td = 202, armor_asg = 2, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "Mutiple attack abilities, including a command of many offensive spells, make the sand devil a most dangerous adversary. Its name comes from the appearance of its leathery, yellowish, reptilian head crowned with two long, upright, black horns. The sand devil swirls in and out of areas, constantly rotating to keep the wind and dust whipping around it. This allows its sharp claws to remain hidden, emerging suddenly from the sandstorm to slash at surprised foes.", attacks = { { type = "claw_attack" }, { type = "pound_attack" } }, spells = { "Minor Shock", "Energy Maelstrom" }, abilities = { "water_bolt", "fire_bolt", "cold_flare", "web_immobilize", "tail_spike_volley", "entangle", "lesser_shroud_120", "wall_of_force_140", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_targeting_425", "elemental_barrier_430", "mobility_618" } },

    -- Level 49
    { template_id = "waern", base_template = "barghest", name = "waern", level = 49, spawn_areas = { "Bonespear Tower" }, roam_areas = { "Bonespear Tower" }, family = "canine", classification = "corporeal_undead", body_type = "quadruped", ds_ranged = 266, td = 200, udf = 276, preferred_stance = "offensive", stance_profile = "caster", description = "The waern is a vicious-looking embodiment of canine malice and tenacity. The waern's fiendish green eyes glow with insane appetite and her mangy pelt is so ragged, the rotting bones show through in spots. Long, malicious teeth curve out of the waern's rotting muzzle, and the tail that curves over the waern's back is hardly more than segments of bone interspersed with a few pieces of fuzzy, matted hair. Floating over the ground, her paws scarcely leaving a track, the waern dodges almost quicker than the eye can follow.", attacks = { { type = "claw" } } },

    -- Level 50
    { template_id = "greater_faeroth", name = "greater faeroth", level = 50, spawn_areas = { "Gyldemar Forest" }, roam_areas = { "Gyldemar Forest" }, family = "faeroth", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 208, td = 194, armor_asg = 12, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "The 'greater faeroth' looks as though he might be a relative to a yeti, although his fur is a mottled dingy brown and carries a pungent stench. Similar to its lesser cousin, the greater faeroth stands on mighty forelimbs that lift his entire body into the air. Much more powerful hind legs dangle with sharp, filthy claws extruding. The beast stands at least seven feet tall, with a face that might look human if not for the heavy brow and deeply set eyes. Black lips curl over ivory white teeth that appear to drip some sort of vile green liquid.", attacks = { { type = "bite" }, { type = "claw" }, { type = "pound" } } },
    { template_id = "shriveled_icy_creeper", base_template = "dybbuk", name = "shriveled icy creeper", level = 50, spawn_areas = { "Frozen Bramble" }, roam_areas = { "Frozen Bramble" }, family = "creeper", classification = "corporeal_undead", body_type = "hybrid", td = 203, udf = 230, preferred_stance = "forward", stance_profile = "berserker", description = "Looking nearly to expire, this creeper definitely falls into the unhealthy category but don't let looks fool you. If you or a friend falls into it, it is likely that you or they will fall into an unhealthy ... or dead category too!", attacks = { { type = "melee_stab" } } },

    -- Level 52
    { template_id = "seeker", base_template = "baesrukha", name = "seeker", level = 52, spawn_areas = { "Mount Aenatumgana" }, roam_areas = { "Mount Aenatumgana" }, family = "humanoid", classification = "corporeal_undead", body_type = "biped", hp = 240, hp_variance = 24, ds_bolt = 337, td = 246, armor_asg = 1, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "Approaching from afar, the seeker looks for all the world like a hunched over traveller, barely getting by with the aid of her walking stick, shuffling along and muttering to herself. Upon close examination, though, the seeker projects a grisly visage of skeletal madness. Some strange magic has caused her eyelids to grow completely over her eyes, rendering her blind, yet the rest of her face is totally fleshless. Grinning fiendishly, the seeker unerringly pursues her goal - the Eye of the Drake and the path through to the Rift.", spells = { "Elemental Dispel" }, abilities = { "earthen_fury_caster", "gas_cloud", "strength_509", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "mass_blur_911", "prismatic_guard_905" } },
    { template_id = "snow_madrinol", name = "snow madrinol", level = 52, spawn_areas = { "Gossamer Valley" }, roam_areas = { "Gossamer Valley" }, family = "madrinol", body_type = "quadruped", hp = 260, hp_variance = 26, ds_melee = 246, ds_bolt = 260, td = 222, armor_asg = 15, armor_natural = true, preferred_stance = "offensive", stance_profile = "skirmisher", description = "The heavily armored snow madrinol moves ponderously through the area searching for easy prey to consume. Plates of extremely thick slate grey skin cover this quadruped on nearly all its exterior surfaces except its long, leathery tail and cupped, upright ears. Tufts of off-white fur protrude between the plates, however, giving the impression that the madrinol is wearing pieces of armor rather than a total covering. Unique to the snow madrinol seems to be its flared, circular hooves. Sharp claws protrude from all sides of each hoof, allowing the creature to grip the ice or frozen ground for greater stability.", attacks = { { type = "bite" }, { type = "claw" } } },
    { template_id = "wooly_mammoth", base_template = "snow_madrinol", name = "wooly mammoth", level = 52, spawn_areas = { "Arctic Tundra" }, roam_areas = { "Arctic Tundra" }, family = "elephantid", body_type = "quadruped", hp = 400, hp_variance = 40, ds_bolt = 257, td = 172, preferred_stance = "offensive", stance_profile = "skirmisher", description = "Very few creatures stand in the path of a wooly mammoth for long. This huge mammal is covered with long, thick, dark brown hair that protects him against freezing conditions. His flexible trunk is flanked by two heavy ivory tusks that curl up and back toward his wide, flapping ears. An angered wooly mammoth has been known to pick up a reckless adventurer and throw the hapless person out of sight." },

    -- Level 53
    { template_id = "ice_golem", name = "ice golem", level = 53, spawn_areas = { "Mount Aenatumgana" }, roam_areas = { "Mount Aenatumgana" }, family = "golem", classification = "magical", body_type = "biped", hp = 500, hp_variance = 50, ds_bolt = 225, td = 219, preferred_stance = "forward", stance_profile = "berserker", description = "The ice golem is a mammoth construct of freezing cold ice and snow. Towering over twenty feet in height, this ice golem surely weighs several tons. The ice golem's rime-covered face displays its sharp, angular features, over which whisps from its frosty brow droop.", attacks = { { type = "pound" }, { type = "stomp" } }, abilities = { "tremors" } },
    { template_id = "lesser_ice_elemental", name = "lesser ice elemental", level = 53, spawn_areas = { "Mount Aenatumgana" }, roam_areas = { "Mount Aenatumgana" }, family = "elemental", classification = "extra_planar", body_type = "hybrid", hp = 400, hp_variance = 40, ds_melee = 330, ds_bolt = 302, td = 240, preferred_stance = "guarded", stance_profile = "caster", description = "The ice elemental is an amorphous conglomeration of ice and snow that writhes and moves about with a mind of its own. The intense cold generated by the ice elemental is nearly unbearable.", attacks = { { type = "ensnare" } }, spells = { "Elemental Dispel" }, abilities = { "cold_flare", "tremors", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "prismatic_guard_905" } },
    { template_id = "sabre_tooth_tiger", name = "sabre-tooth tiger", level = 53, spawn_areas = { "Arctic Tundra", "Mount Aenatumgana" }, roam_areas = { "Arctic Tundra", "Mount Aenatumgana" }, family = "feline", body_type = "quadruped", hp = 400, hp_variance = 40, ds_melee = 220, ds_bolt = 243, td = 186, preferred_stance = "offensive", stance_profile = "skirmisher", description = "The huge sabre-tooth tiger is obviously a formidable predator, measuring more than 15 feet from the nose to the tip of her tail. Flexing massive shoulders above powerful forelegs, the tiger growls and snarls, exposing the elongated canines that give her her name. The tiger's magnificent striped pelt gradates from a soft tan undertone along the spine to a powder white on belly and legs.", attacks = { { type = "bite" }, { type = "charge" } } },
    { template_id = "stone_sentinel", base_template = "ice_golem", name = "stone sentinel", level = 53, spawn_areas = { "Darkstone Castle" }, roam_areas = { "Darkstone Castle" }, family = "golem", classification = "magical", body_type = "biped", ds_ranged = 103, td = 168, udf = 446, armor_asg = 20, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "Comprised of solid blocks of granite, the immense stone sentinel stands and moves very stiffly. Each portion of its anatomy is chiseled in rectangular pieces with sharp right angles. It is not apparent how this animated construct moves, or how it even stays together, but somehow it does both effectively. The attacks of a stone sentinel carry the weight of tons of rock behind them. Being in the path of one is not an experience to be recommended.", attacks = { { type = "pound" } }, spells = { "Fireball", "Mind Jolt", "Silence" }, abilities = { "tremors", "earthen_fury_caster" }, immune = { "stun" } },

    -- Level 54
    { template_id = "animated_slush", name = "animated slush", level = 54, spawn_areas = { "Gossamer Valley" }, roam_areas = { "Gossamer Valley" }, family = "elemental", classification = "magical", body_type = "hybrid", hp = 260, hp_variance = 26, ds_bolt = 250, td = 223, armor_asg = 1, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "An animated slush could easily be mistaken for a huge pile of snow that has partially melted then refrozen. It presents a squat, icy white cone ten feet wide at the base but only rising five feet high. The edges are slightly transparent and tinged a light blue, while the interior is dark, with portions seeming more solid than others. Rippling over the terrain, its exact motion indiscernible, the animated slush unerringly finds its prey, yet it displays no sensory glands of any type.", attacks = { { type = "pound" } }, spells = { "Torment" }, abilities = { "water_bolt", "cold_flare" } },
    { template_id = "ethereal_mage_apprentice", base_template = "spectral_miner", name = "ethereal mage apprentice", level = 54, spawn_areas = { "The Citadel" }, roam_areas = { "The Citadel" }, family = "ghost", classification = "non_corporeal_undead", body_type = "biped", hp = 240, hp_variance = 24, preferred_stance = "forward", stance_profile = "berserker", description = "Twisted and warped in the service of the Council of Twelve, the 'apprentice' floats several inches over the floor, hunched over, gazing at his surroundings with abnormally large yellow-hued eyes framed by translucent, rotting and pestilent skin. Draped over his broken form are the remnants of a once simple, but finely crafted robe. Cinching the robe at the waist is a thick black belt, adorned with numerous leather pouches once used to hold the supplies desired by his arcane master." },
    { template_id = "skayl", name = "skayl", level = 54, spawn_areas = { "Lava Flows" }, roam_areas = { "Lava Flows" }, family = "elemental", classification = "magical", body_type = "hybrid", hp = 300, hp_variance = 30, ds_melee = 167, td = 235, armor_asg = 16, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "Flame suddenly hisses and spits from thin air, which shimmers in the resulting smoke like reflective crystal. Then abruptly, the air roils and begins to take on form. In mere heartbeats, it becomes obvious that the transparent bubble of conflagration is a sentient being. The skayl opens its gaping maw of fire and bellows a malign growl that is more felt than heard. In the next instant, the skayl melts down then reforms a short distance away, leaving a drift of smoke in its wake like a fraying shadow.", attacks = { { type = "closed_fist" }, { type = "ensnare_attack" } }, abilities = { "earthen_fury_caster", "elemental_bias_508", "strength_509", "mass_blur_911" } },

    -- Level 55
    { template_id = "eidolon", name = "eidolon", level = 55, spawn_areas = { "Bonespear Tower" }, roam_areas = { "Bonespear Tower" }, family = "eidolon", classification = "non_corporeal_undead", body_type = "biped", hp = 240, hp_variance = 24, ds_melee = 348, td = 254, udf = 286, armor_asg = 1, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "The eidolon is a nightmarish vision of pure evil, appearing from the shadows like a disconcerting fragment of thought that haunts you relentlessly. The eidolon's eyes shine out of its ephemeral silhouette like twin coals, radiating hatred and hunger. The monstrous apparition is as big as it is misshapen, towering over a tall giantman as it moves in rapid spurts that defy the eye's ability to follow its progress. As it conjures and strikes, its extremities contort and blur through each other, amplifying its grotesque demeanor.", attacks = { { type = "closed_fist" } }, spells = { "Pain", "Curse", "Pestilence", "Torment", "Repel (fear)" }, abilities = { "spirit_warding_i_101", "spirit_defense_103", "lesser_shroud_120", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414" } },
    { template_id = "grisly_corpse_hulk", base_template = "seeker", name = "grisly corpse hulk", level = 55, spawn_areas = { "Crawling Shore" }, roam_areas = { "Crawling Shore" }, family = "humanoid", classification = "corporeal_undead", body_type = "biped", preferred_stance = "forward", stance_profile = "berserker", description = "A grisly corpse hulk is a collection of corpse parts roughly arranged into a humanoid form within a handspan of a giant's height. Milky pinkish fluid drips from the uneven stitches that hold its body together. Its eyes are tiny and appear piggish in such an oversized head. They hold only a rudimentary spark of intellect. Appraisal: The corpse hulk is large in size, about eight feet high in its current state.", attacks = { { type = "stomp_attack" }, { type = "closed_fist" }, { type = "ensnare" } }, abilities = { "tackle" } },
    { template_id = "nightmare_steed", base_template = "shadow_steed", name = "nightmare steed", level = 55, spawn_areas = { "Darkstone Castle", "The Broken Lands" }, roam_areas = { "Darkstone Castle", "The Broken Lands" }, family = "equine", classification = "non_corporeal_undead", body_type = "quadruped", preferred_stance = "offensive", stance_profile = "skirmisher", description = "The mighty nightmare steed stands defiantly at all around it staring blankly with cold rage, filled with malice and a clear desire to rend flesh from limb to limb. It has midnight black hair and a silky silver mane with occasional black streaks. The eyes of a nightmare steed shine with a brilliant red glow that never are seen to blink very often, if at all." },
    { template_id = "stone_troll", name = "stone troll", level = 55, spawn_areas = { "Thanatoph" }, roam_areas = { "Thanatoph" }, family = "troll", body_type = "biped", hp = 400, hp_variance = 40, ds_melee = 302, td = 228, armor_asg = 16, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "Towering above you, the stone troll is an ugly, brutish looking creature. Its marbled grey skin is covered with pocks and divots. This lumpy grotesque troll grins maniacally at you, sending cracks and fissures across its face.", attacks = { { type = "thrown" }, { type = "war_hammer" } }, spells = { "Unbalance" }, abilities = { "tremors" } },

    -- Level 56
    { template_id = "decaying_citadel_guardsman", name = "decaying citadel guardsman", level = 56, spawn_areas = { "The Citadel" }, roam_areas = { "The Citadel" }, family = "humanoid", classification = "corporeal_undead", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 303, ds_ranged = 216, ds_bolt = 259, td = 197, armor_asg = 16, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "Blazing white balefire fills the eye sockets of the 'Citadel guardsman', who is dressed in the deteriorating remains of a once resplendent uniform of buff and blue. The taut, sinewy flesh stretched over the guardsman's exposed face and hands is riddled with gaping holes that reveal the desiccated remains of muscle and cartilage. Gripped firmly in hands of exposed bone and flesh is an immaculate Hammer of Kai, which is aflame in a radiant white fire that burns along its blade. ", attacks = { { type = "hammer_of_kai" } }, abilities = { "charge_knockdown", "trip" } },
    { template_id = "glacial_morph", name = "glacial morph", level = 56, spawn_areas = { "Gossamer Valley" }, roam_areas = { "Gossamer Valley" }, family = "elemental", classification = "magical", body_type = "hybrid", hp = 260, hp_variance = 26, ds_bolt = 267, td = 232, udf = 466, armor_asg = 12, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "Chunks of ice appear to be held together by strands of organic material to form the rough outline of a bipedal creature. The chunks have no specific shape, and some are larger than others without direct relation to placement on glacial morph. Often the glacial morph draws in on itself, the chunks rearranging and reattaching to form a considerably different shape, and it seems to be able to change color at will to match its surroundings. The glacial morph peers out from two malevolent eyes set deeply in a 'head' of ice. Strangely, the head does not always appear to be on top of the torso.", attacks = { { type = "pound" }, { type = "ensnare" } }, abilities = { "hide" } },
    { template_id = "lava_golem", name = "lava golem", level = 56, spawn_areas = { "Eye of V'Tull" }, roam_areas = { "Eye of V'Tull" }, family = "golem", classification = "magical", body_type = "biped", hp = 500, hp_variance = 50, ds_melee = 220, td = 221, armor_asg = 12, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "The lava golem is a mammoth construct of molten red hot rock and white hot eyes. Towering over twelve feet in height, it surely weighs several tons.", attacks = { { type = "pound_attack" }, { type = "stomp_attack" } } },

    -- Level 57
    { template_id = "gaunt_feral_selkie", base_template = "sea_nymph", name = "gaunt feral selkie", level = 57, spawn_areas = { "Crawling Shore" }, roam_areas = { "Crawling Shore" }, family = "fey", body_type = "biped", preferred_stance = "guarded", stance_profile = "caster", description = "Clad in sealskin and sailcloth, the feral selkie is a half-krolvin in his middle years. Her hair is unkempt and her eyes are wild and unfocused. Rattling bones, dried iceblossoms, and bits of kelp adorn her ritualistic attire, held in place by bits of fraying twine. Unwashed and obviously addled, the selkie looks as if she has one foot firmly in a world that you cannot see. Or: The selkie's large, dark eyes hold more than a glimmer of unnatural intellect. His fur is soft and sleek over an agile musculature more suited to the water than dry land. The selkie's sharp teeth are yellowed and an overwhelming odor of fish guts rises from his mouth in a noxious cloud. Appraisal: The feral selkie is medium in size, about six feet high in his current state.", spells = { "Hand of Tonis" }, abilities = { "cold_flare", "earthen_fury_caster", "powerful_blow", "charge_knockdown", "trip", "iron_skin_1202", "war_hardened" } },

    -- Level 58
    { template_id = "massive_pyrothag", name = "massive pyrothag", level = 58, spawn_areas = { "Lava Flows" }, roam_areas = { "Lava Flows" }, family = "pyrothag", classification = "magical", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 281, td = 244, armor_asg = 12, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "The pyrothag is a huge creature, towering over the tallest of giantmen. Scorched black by the heat of its environment, its thick skin protects it from blows and the hostile lava flows. The most striking thing aside from its size, is the lack of facial features. A smooth face matching its smooth black skin leaves one wondering how such a thing could have evolved.", attacks = { { type = "quarterstaff" }, { type = "stomp_attack" }, { type = "pound_attack" } } },
    { template_id = "rotting_citadel_arbalester", name = "rotting citadel arbalester", level = 58, spawn_areas = { "The Citadel" }, roam_areas = { "The Citadel" }, family = "humanoid", classification = "corporeal_undead", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 272, ds_ranged = 261, ds_bolt = 251, td = 224, armor_asg = 12, armor_natural = false, preferred_stance = "guarded", stance_profile = "ranged", description = "A rusted conical helmet, wrapped in a band of buff and blue, sits above the empty eye sockets of a skull draped in the rotting remains of a rotting Citadel arbalester's face. Residual juices drip from the head of the arbalester and down a ragged surcoat of buff and blue cinched with a tattered leather belt buckled with a rusted shield stamped with a large letter \"E.\" A quiver hangs from the belt, flush with feathered bolts and within easy reach of the arbalester's gloved hands.", attacks = { { type = "heavy_crossbow" } }, abilities = { "trip" } },
    { template_id = "shan_sorceress", base_template = "grutik_shaman", name = "shan sorceress", level = 58, spawn_areas = { "Forgotten Vineyard" }, roam_areas = { "Forgotten Vineyard" }, family = "shan", body_type = "biped", preferred_stance = "guarded", stance_profile = "caster", description = "{{addmetext}}" },
    { template_id = "stone_giant", name = "stone giant", level = 58, spawn_areas = { "Thanatoph" }, roam_areas = { "Thanatoph" }, family = "giant", body_type = "biped", hp = 600, hp_variance = 60, ds_melee = 317, td = 241, udf = 474, armor_asg = 20, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "Looming high above you, taller than three of the tallest giantmen, this stone giant dominates the surrounding area. The stone giant's skin is a smooth dull grey with mottled brown splotches and its eyes, concealed under a heavy brow, gleam black with hatred.", attacks = { { type = "pound" }, { type = "stomp" }, { type = "war_mattock" } }, spells = { "Hurl Boulder", "Unbalance" }, abilities = { "earthen_fury_caster", "natural_colors_601", "resist_elements_602", "self_control_613" } },

    -- Level 59
    { template_id = "black_forest_viper", name = "black forest viper", level = 59, spawn_areas = { "Blighted Forest" }, roam_areas = { "Blighted Forest" }, family = "reptilian", body_type = "ophidian", hp = 260, hp_variance = 26, ds_melee = 272, ds_bolt = 292, td = 246, armor_asg = 8, armor_natural = true, preferred_stance = "offensive", stance_profile = "skirmisher", description = "The black forest viper is a shadowy charcoal grey, complemented by its paler grey underbelly. Small horned protrusions rise above each of the viper's eyes, giving the creature a devilish appearance. Much larger than a typical snake, the viper is nearly ten feet long, and it is quite capable of slaying foes as large as a human. The snake's lazy movement belies its ability to strike rapidly when threatened.", attacks = { { type = "bite" } } },
    { template_id = "bony_tenthsworn_occultist", base_template = "swamp_hag", name = "bony tenthsworn occultist", level = 59, spawn_areas = { "Crawling Shore" }, roam_areas = { "Crawling Shore" }, family = "humanoid", body_type = "biped", td = 259, armor_asg = 2, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "Robed and hooded, the Tenthsworn occultist has fervent eyes the color of dried blood and the sort of pallor earned from days spent out of the sun. His dark robes are stitched with serpentine patterns in crimson, a theme repeated in the symbol at his throat, which takes the form of a pair of intertwined asps. The occultist's face is hollow and he looks as if he has not eaten in some time, though perhaps the zeal within him has burned all spare flesh away. Appraisal: The Tenthsworn occultist is small in size, about four feet high in his current state.", spells = { "Blood Burst", "Condemn", "Grasp of the Grave" } },
    { template_id = "massive_black_boar", name = "massive black boar", level = 59, spawn_areas = { "Blighted Forest", "Red Forest" }, roam_areas = { "Blighted Forest", "Red Forest" }, family = "suine", body_type = "quadruped", hp = 400, hp_variance = 40, ds_melee = 200, td = 246, armor_asg = 12, armor_natural = true, preferred_stance = "offensive", stance_profile = "skirmisher", description = "The black boar snorts loudly and scrapes at the ground, peering around with his close-set, bloodshot eyes in hopes of finding something he can gore into a bloody pulp or pound into the earth. His body is covered with coarse, black hair, and dull grey tusks protrude from each side of his gaping mouth. A good ten feet long from dripping snout to curly tail and weighing more than a ton, the black boar moves with surprising speed and dexterity as he bears down, squealing furiously, on his intended prey. The murderous glint in the boar's eyes betrays an intelligence much greater than his mundane kin.", attacks = { { type = "charge_attack" }, { type = "impale_attack" }, { type = "bite_attack" } } },

    -- Level 60
    { template_id = "black_forest_ogre", name = "black forest ogre", level = 60, spawn_areas = { "Blighted Forest", "Aradhul Road" }, roam_areas = { "Blighted Forest", "Aradhul Road" }, family = "ogre", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 261, ds_bolt = 229, td = 246, armor_asg = 12, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "A black forest ogre plods through the countryside, her immense arm and leg muscles rippling with each wide step. An oversized, slavering lower jaw and two long, pointed, lower teeth give the ogre a constant toothy sneer. The thick bones of her protruding forehead shade beady black eyes, and if there is any intelligence in those eyes, it is completely obscured by the black forest ogre's vicious malevolence. Short, coal black hair covers the creature's body and appendages, though in many places the hair is broken by long, deep scars.", attacks = { { type = "dhara_dhara_rogues" }, { type = "closed_fist_closed_fist_wizards" } }, spells = { "Hand of Tonis", "Cold Snap", "Elemental Dispel", "Elemental Focus" }, abilities = { "acid_spray", "fire_bolt", "cold_flare", "tremors", "call_wind", "elemental_targeting_425", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_barrier_430", "prismatic_guard_905", "mass_blur_911" } },
    { template_id = "fire_elemental", name = "fire elemental", level = 60, spawn_areas = { "Eye of V'Tull" }, roam_areas = { "Eye of V'Tull" }, family = "elemental", classification = "extra_planar", body_type = "hybrid", hp = 260, hp_variance = 26, ds_melee = 462, ds_bolt = 282, td = 248, udf = 463, armor_asg = 10, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "The fire elemental is a massing of flames that flow and flicker with a life of their own. The intense heat generated by the fire elemental is nearly unbearable.", attacks = { { type = "ensnare" } }, abilities = { "tremors" } },
    { template_id = "putrefied_citadel_herald", name = "putrefied citadel herald", level = 60, spawn_areas = { "The Citadel" }, roam_areas = { "The Citadel" }, family = "humanoid", classification = "corporeal_undead", body_type = "biped", hp = 240, hp_variance = 24, ds_melee = 303, ds_ranged = 279, ds_bolt = 239, td = 283, armor_asg = 2, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "Maggots crawl and writhe in the eye sockets of a putrefied Citadel herald. Replete in immaculate costume, the herald stands stiffly with an expression of disdain on her withered face of grey putrified skin. A large signet ring graces one of her two large wrinkled hands patiently folded one over the other. A polished, leather scroll case hangs at the herald's side, embossed with a large letter \"E.\"", attacks = { { type = "runestaff" } }, spells = { "Web Bolt", "Bind", "Interference", "Searing Light", "Silence", "Unbalance", "Wither", "Divine Wrath" }, abilities = { "flame_aura", "spirit_strike", "web_immobilize", "lesser_shroud_120", "spirit_shield_202" } },
    { template_id = "shan_empath", base_template = "grutik_shaman", name = "shan empath", level = 60, spawn_areas = { "Forgotten Vineyard" }, roam_areas = { "Forgotten Vineyard" }, family = "shan", body_type = "biped", preferred_stance = "guarded", stance_profile = "caster", description = "{{addmetext}}", abilities = { "spirit_strike" } },
    { template_id = "winged_viper", name = "winged viper", level = 60, spawn_areas = { "Red Forest" }, roam_areas = { "Red Forest" }, family = "reptilian", body_type = "avian", hp = 260, hp_variance = 26, ds_ranged = 193, ds_bolt = 206, td = 247, armor_asg = 12, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "The viper has a sinuous scaley body of purest white, feathered from snout to tail. Two majestic wings arch from its body roughly one-third of the way down its length. The viper's mouth is filled with long, needle sharp fangs, and its forked tongue flickers constantly to taste the air hungrily.", attacks = { { type = "bite" } }, spells = { "Elemental Strike", "Elemental Dispel" }, abilities = { "cold_flare", "fire_bolt", "shock_burst", "gas_cloud", "tremors", "sonic_wail", "elemental_barrier_430", "elemental_defense_iii_414" } },

    -- Level 61
    { template_id = "desiccated_half_krolvin_strigoi", base_template = "rotting_citadel_arbalester", name = "desiccated half-krolvin strigoi", level = 61, spawn_areas = { "Crawling Shore" }, roam_areas = { "Crawling Shore" }, family = "humanoid", classification = "corporeal_undead", body_type = "biped", preferred_stance = "forward", stance_profile = "berserker", description = "The corpse-like face of the half-krolvin strigoi bears little resemblance to a living half-krolvin save in its heavy brow and dense brows. Eyes like pits of shadow stare out from the sunken hollows of the strigoi's altered visage, hungry and hateful. The strigoi has yellowed fangs that distend her lips in an ugly fashion. Her motions are distinctly unnatural, fluid in a way that a living being's are not. Appraisal: The half-krolvin strigoi is medium in size, about six feet high in her current state.", attacks = { { type = "closed_fist" }, { type = "ensnare_attack" } } },

    -- Level 62
    { template_id = "illoke_mystic", base_template = "stone_giant", name = "illoke mystic", level = 62, spawn_areas = { "Thanatoph" }, roam_areas = { "Thanatoph" }, family = "giant", body_type = "biped", hp = 600, hp_variance = 60, td = 244, armor_asg = 16, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "Massive and imposing, the Illoke mystic towers over adventurers. It is more than three times the size of the largest giantman, with smooth grey skin and deep black eyes that glare out from under a heavy brow. The eyes regard potential victims with disdain, as if they were nothing more than an offering to be sacrificed. Chiseled deep into the forehead of the shaman, the symbol of Illoke glows red with power.", abilities = { "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_targeting_425", "natural_colors_601", "resist_elements_602" } },
    { template_id = "phantasmal_bestial_swordsman", base_template = "ethereal_mage_apprentice", name = "phantasmal bestial swordsman", level = 62, spawn_areas = { "The Citadel" }, roam_areas = { "The Citadel" }, family = "ghost", classification = "non_corporeal_undead", body_type = "biped", ds_ranged = 214, td = 223, preferred_stance = "forward", stance_profile = "berserker", description = "Muscular and lean, a phantasmal bestial swordsman stands shorter than most giantmen, dressed only in the ragged remains of leather pants. His skin is the color of a starless night and is wrapped tightly around brawny arms and legs. Long, pointed ears extend from the sides of his bald head with large, pitch black eyes set closely together over two large slits in place of a proper nose. Long yellow canines stick up from behind the lower lip of the swordsman.", attacks = { { type = "hammer_of_kai" } }, abilities = { "tackle" } },
    { template_id = "shan_bardess", base_template = "grutik_shaman", name = "shan bardess", level = 62, spawn_areas = { "Forgotten Vineyard" }, roam_areas = { "Forgotten Vineyard" }, family = "shan", body_type = "biped", preferred_stance = "guarded", stance_profile = "caster", description = "{{addmetext}}", attacks = { { type = "lance" } } },
    { template_id = "stone_mastiff", name = "stone mastiff", level = 62, spawn_areas = { "Thanatoph" }, roam_areas = { "Thanatoph" }, family = "canine", classification = "magical", body_type = "quadruped", hp = 400, hp_variance = 40, ds_melee = 279, td = 260, armor_asg = 20, armor_natural = true, preferred_stance = "offensive", stance_profile = "skirmisher", description = "The stone mastiff is a huge grey dog that seems to be formed of living stone. The mastiff is rectangular in shape, and the length of the mastiff from forechest to rear is around five feet. Massive and heavy boned, with a powerful muscle structure, this stone mastiff presents a formidable foe.", attacks = { { type = "bite" }, { type = "claw" } }, abilities = { "charge_knockdown" } },

    -- Level 63
    { template_id = "ice_elemental", base_template = "cold_guardian", name = "ice elemental", level = 63, spawn_areas = { "Mount Aenatumgana" }, roam_areas = { "Mount Aenatumgana" }, family = "elemental", classification = "extra_planar", body_type = "hybrid", preferred_stance = "guarded", stance_profile = "caster", description = "The ice elemental is an amorphous conglomeration of ice and snow that writhes and moves about with a mind of its own. The intense cold generated by the ice elemental is nearly unbearable." },
    { template_id = "massive_troll_king", name = "massive troll king", level = 63, spawn_areas = { "Darkstone Castle" }, roam_areas = { "Darkstone Castle" }, family = "troll", body_type = "biped", hp = 400, hp_variance = 40, ds_melee = 262, ds_ranged = 249, ds_bolt = 237, td = 276, armor_asg = 12, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "'Massive troll kings' are the largest, ugliest, dumbest, and most powerful creatures in the troll family. This fierce monster is roughly humanoid, standing nearly 9 feet tall, with long arms ending in razor-sharp claws. Dark green and covered with ugly warts, this hideous being appears unintelligent yet incredibly strong.", attacks = { { type = "bite" }, { type = "claw" }, { type = "bite_enraged" }, { type = "claw_enraged" } } },
    { template_id = "sheruvian_harbinger", name = "sheruvian harbinger", level = 63, spawn_areas = { "Darkstone Castle", "The Broken Lands" }, roam_areas = { "Darkstone Castle", "The Broken Lands" }, family = "humanoid", body_type = "biped", hp = 240, hp_variance = 24, ds_melee = 231, td = 248, preferred_stance = "guarded", stance_profile = "caster", description = "The Sheruvian harbinger is a handsome woman with hypnotic eyes and fair skin. Her demeanor appears emotionless, but you can see some sort of evil fire burning within those dark pupils. A sleek, black breastplate covers most of her torso, and you can see it is made of fine quality. The mere look of the harbinger reminds most people of the tales of the Harbinger of Chaos, spawned forth to do great evil.", attacks = { { type = "broadsword" } }, spells = { "Bind", "Frenzy", "Mind Jolt", "Silence" }, abilities = { "heroism_215", "spirit_strike", "lesser_shroud_120", "spirit_shield_202", "spirit_warding_i_101" } },

    -- Level 64
    { template_id = "direbear", name = "direbear", level = 64, spawn_areas = { "Red Forest" }, roam_areas = { "Red Forest" }, family = "bear", body_type = "quadruped", hp = 400, hp_variance = 40, ds_melee = 244, ds_bolt = 184, td = 259, udf = 318, armor_asg = 16, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "The direbear is a huge powerful beast with baleful red eyes that seem to bore through to the very soul. Impressively large bone deposits protrude across the breadth of the beast's back and neck. Large teeth that seem too big even for the massive maw can easily be seen even when the powerful jaws are closed. Mist, or perhaps tendrils of smoke, occasionally drift up from the flaring nostrils. Sharp eyes, a sense of smell to match, and a cunning said to rival demons make a direbear something to be avoid. {{TOC limit}}", attacks = { { type = "bite_attack" }, { type = "claw_attack" } }, spells = { "Bertrandt's Bellow", "Gerrelle's Growl", "Red eyes (AS boost)" }, abilities = { "charge_knockdown" } },
    { template_id = "fire_sprite", name = "fire sprite", level = 64, spawn_areas = { "Glaes Caverns" }, roam_areas = { "Glaes Caverns" }, family = "fey", body_type = "biped", hp = 240, hp_variance = 24, ds_melee = 403, ds_ranged = 298, ds_bolt = 287, td = 290, udf = 414, armor_asg = 1, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "At first glance, the fire sprite looks like nothing more than a ball of whirling flame, spitting smoke and ricocheting about the rocks like a dervish. Gradually, her form coalesces, extending elongated arms and fingers, and short gnarled legs from the sphere of fire. The fire sprite's hideous features are pulled into a grimace of hate, and her eyes are like two glowing coals, which spout sparks as the creature wavers in and out of her tenuous configuration.", attacks = { { type = "closed_fist" } }, spells = { "Elemental Dispel" }, abilities = { "fire_bolt", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414" } },
    { template_id = "grifflet", name = "grifflet", level = 64, spawn_areas = { "Griffin's Keen" }, roam_areas = { "Griffin's Keen" }, family = "griffin", body_type = "hybrid", hp = 260, hp_variance = 26, ds_melee = 265, ds_bolt = 263, armor_asg = 12, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "The grifflet is a young, yet magnificent beast. Mottled brown feathers marked with light splotches cover the grifflet's front legs, forebody, and wings, while the creature's eagle-like head is almost completely grey. The rear half of the grifflet's body is that of a young lion, with short, pale yellow fur and a long feline tail. Even at this immature stage of life, the horse-sized grifflet is a deadly foe.", attacks = { { type = "impale" }, { type = "bite" }, { type = "claw" } }, abilities = { "call_wind", "sonic_wail" } },
    { template_id = "shan_shaman", base_template = "grutik_shaman", name = "shan shaman", level = 64, spawn_areas = { "Forgotten Vineyard" }, roam_areas = { "Forgotten Vineyard" }, family = "shan", body_type = "biped", preferred_stance = "guarded", stance_profile = "caster", description = "{{addmetext}}" },

    -- Level 66
    { template_id = "emaciated_hierophant", name = "emaciated hierophant", level = 66, spawn_areas = { "Temple Wyneb" }, roam_areas = { "Temple Wyneb" }, family = "humanoid", body_type = "biped", hp = 240, hp_variance = 24, ds_melee = 260, td = 288, armor_asg = 12, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "The emaciated hierophant stands short for a human, and might pass for one except for the storm grey eyes that swirl with unearthly energy. Long robes that appear to float in the air gap to reveal an ornate tunic and breeches with polished green leather boots to the knee. A long golden chain hangs about his neck, a small glowing red crystal suspended as a pendant there. Intricate tattoos cover his flesh, drawing ornate and unrecognizable patterns that glow a dull red and seem to pulse along as if it were blood.", attacks = { { type = "espadon" } }, spells = { "Unbalance", "Tangle Weed" }, abilities = { "sonic_wail", "tail_spike_volley", "spirit_strike", "spirit_defense_103", "lesser_shroud_120", "natural_colors_601", "resist_elements_602", "mobility_618" } },
    { template_id = "red_tsark", name = "red tsark", level = 66, spawn_areas = { "Eye of V'Tull", "Glaes Caverns" }, roam_areas = { "Eye of V'Tull", "Glaes Caverns" }, family = "reptilian", body_type = "biped", hp = 400, hp_variance = 40, ds_melee = 328, ds_bolt = 223, td = 298, armor_asg = 12, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "Circling and pacing, the red tsark creeps closer, her eyes glowing red with fury. The scaled creature moves constantly, crouched on her powerful back legs like a tightly wound spring, ready to launch an attack at any opportunity. Small front legs are held poised in front of the reptile's chest, armed with formidable claws that could easily disembowel an unwary adversary. Smoke trails from the red tsark's nostrils, punctuated by flames each time she snorts a challenge." },
    { template_id = "shan_rogue", base_template = "gnoll_ranger", name = "shan rogue", level = 66, spawn_areas = { "Forgotten Vineyard" }, roam_areas = { "Forgotten Vineyard" }, family = "shan", body_type = "biped", preferred_stance = "guarded", stance_profile = "ranged", description = "{{addmetext}}" },
    { template_id = "supple_ivasian_inciter", name = "supple ivasian inciter", level = 66, spawn_areas = { "Den of Rot" }, roam_areas = { "Den of Rot" }, family = "humanoid", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 216, ds_bolt = 254, td = 265, udf = 372, armor_asg = 11, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "A supple Ivasian inciter is a surpassingly attractive figure clad in a loose silken shirt of shimmering green cloth of a vivid bile green hue and a darker loincloth. More than just a hint of zealotry glimmers in her kohl-rimmed eyes. She wears a glinting steel symbol, painted red and bordered in a wreath of tentacles, that depicts a stylized wisp of green smoke.", attacks = { { type = "kick" }, { type = "whip" } }, abilities = { "spirit_strike", "tail_spike_volley" } },

    -- Level 67
    { template_id = "illoke_shaman", name = "illoke shaman", level = 67, spawn_areas = { "Thanatoph" }, roam_areas = { "Thanatoph" }, family = "giant", body_type = "biped", hp = 600, hp_variance = 60, td = 268, armor_asg = 16, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "Massive and imposing, the Illoke shaman towers over adventurers. It is more than three times the size of the largest giantman, with smooth grey skin and deep black eyes that glare out from under a heavy brow. The eyes regard potential victims with disdain, as if they were nothing more than an offering to be sacrificed. Chiseled deep into the forehead of the shaman, the symbol of Illoke glows red with power.", attacks = { { type = "maul" } }, spells = { "Interdiction", "Interference" }, abilities = { "earthen_fury_caster", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_targeting_425", "resist_elements_602" } },
    { template_id = "monstrous_direwolf", name = "monstrous direwolf", level = 67, spawn_areas = { "Red Forest" }, roam_areas = { "Red Forest" }, family = "canine", body_type = "quadruped", hp = 400, hp_variance = 40, ds_melee = 305, ds_bolt = 243, td = 298, armor_asg = 16, armor_natural = true, preferred_stance = "offensive", stance_profile = "skirmisher", description = "The monstrous direwolf is a huge powerful beast with baleful red eyes that seem to bore through to the very soul. Impressively large bone deposits protrude across the breadth of the beast's back and neck. Large teeth that seem too big even for the massive maw can easily be seen even when the powerful jaws are closed. Mist, or perhaps tendrils of smoke, occasionally drift up from the flaring nostrils. Sharp eyes, and a sense of smell to match, and a cunning said to rival demons make a direwolf something to avoid.", attacks = { { type = "bite_attack" }, { type = "claw_attack" } }, abilities = { "powerful_blow" } },
    { template_id = "muscular_supplicant", name = "muscular supplicant", level = 67, spawn_areas = { "Temple Wyneb" }, roam_areas = { "Temple Wyneb" }, family = "humanoid", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 246, td = 283, armor_asg = 12, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "Standing somewhere near average height for a human, the muscular supplicant is a lean frame of wiry muscle covered by scarred and dry skin. A great mop of greasy hair covers her eyes, twisted up in long braids. Intricate tattoos cover the exposed flesh, drawing unrecognizable patterns.", attacks = { { type = "flamberge" } } },
    { template_id = "yeti", name = "yeti", level = 67, spawn_areas = { "Griffin's Keen" }, roam_areas = { "Griffin's Keen" }, family = "yeti", body_type = "biped", hp = 400, hp_variance = 40, ds_melee = 223, td = 283, armor_asg = 12, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "Standing almost twelve feet tall, the 'yeti' is a large humanoid creature covered in long, stringy black and red hair. His domed pate is matted with twigs and dirt, and his heavy brow forms a shelf over his tiny black eyes. With arms nearly long enough to brush the ground, the yeti has a ferociously strong grip and excellent leverage for the tossing of heavy objects. Broad, flat feet provide stability and traction in the icy, mountainous environments that are his normal habitat.", attacks = { { type = "pound" }, { type = "stomp" } }, abilities = { "tremors" } },

    -- Level 68
    { template_id = "athletic_dark_eyed_incubus", name = "athletic dark-eyed incubus", level = 68, spawn_areas = { "Den of Rot" }, roam_areas = { "Den of Rot" }, family = "humanoid", classification = "extra_planar", body_type = "biped", hp = 240, hp_variance = 24, ds_melee = 275, ds_bolt = 275, td = 289, udf = 473, armor_asg = 6, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "Almost lewdly handsome, an athletic dark-eyed incubus moves with the grace of a fencer and has the body of a wrestler. He is bare to the waist and clad only in form-fitting trousers of supple, dark leather. The incubus's eyes are inky black pools that lend an otherworldly quality to his intensely masculine beauty.", attacks = { { type = "ensnare" } }, spells = { "Song of Depression", "Repel (Fear)" }, abilities = { "earthen_fury_caster" } },

    -- Level 69
    { template_id = "lesser_griffin", name = "lesser griffin", level = 69, spawn_areas = { "Griffin's Keen" }, roam_areas = { "Griffin's Keen" }, family = "griffin", body_type = "hybrid", hp = 400, hp_variance = 40, ds_melee = 252, ds_bolt = 244, td = 304, armor_asg = 12, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "The 'lesser griffin' is a magnificent beast, as if designed by the gods to embody fierce and graceful predation. Its front legs, forebody, wings, and head are those of a great eagle, complete with large white feathers and aquiline beak. The rear half of the creature's body is that of a powerful lion, with short tawny fur and a long feline tail. Emphasized by its size, which is larger than a warhorse, the griffin's renowned majestic presence and great bravery have earned the creature a place on many nobles' coats-of-arms.", attacks = { { type = "impale" }, { type = "bite" }, { type = "claw" } }, abilities = { "sonic_wail", "powerful_blow" } },

    -- Level 70
    { template_id = "hunch_backed_dogmatist", name = "hunch-backed dogmatist", level = 70, spawn_areas = { "Temple Wyneb" }, roam_areas = { "Temple Wyneb" }, family = "humanoid", body_type = "biped", hp = 240, hp_variance = 24, td = 397, armor_asg = 5, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "A hunch-backed dogmatist's frail frame has seen many years of toil and abuse. Evidence of such hardship appears in the stooped posture of the dogmatist. A defined hump protrudes from behind the dogmatist's head, easily discerned through layers of clothing and leather armor. The hunch-backed dogmatist's eyes glance frequently from side-to-side, as if constantly waiting for something to appear.", attacks = { { type = "kaskara" } }, spells = { "Mass Interference", "Fervent Reproach", "Censure", "Interdiction", "Spirit Dispel" }, abilities = { "flame_aura", "wall_of_force_140" } },
    { template_id = "krag_yeti", name = "krag yeti", level = 70, spawn_areas = { "Wehntoph" }, roam_areas = { "Wehntoph" }, family = "yeti", body_type = "biped", hp = 400, hp_variance = 40, ds_melee = 287, ds_ranged = 288, ds_bolt = 308, td = 302, armor_asg = 12, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "A towering mound of fur that belies her swift blinding speed, the 'krag yeti' is at home either in the sub-zero wasteland or on rocky mountain tops. The krag yeti's white fur allows an almost perfect blend with the natural surroundings, enabling the creature to move with uncommon stealth. Legendary strength and fury make her a formidable opponent for any who would cross her.", attacks = { { type = "hairy_hand" }, { type = "ensnare" }, { type = "closed_fist" } }, abilities = { "tremors" } },
    { template_id = "seething_pestilent_vision", name = "seething pestilent vision", level = 70, spawn_areas = { "Den of Rot" }, roam_areas = { "Den of Rot" }, family = "humanoid", classification = "non_corporeal_undead", body_type = "hybrid", hp = 240, hp_variance = 24, ds_melee = 262, ds_bolt = 238, td = 296, udf = 309, armor_asg = 12, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "Writhing green smoke comprises the form of a seething pestilent vision. It has only the suggestion of a humanoid form, and a buzzing like that of countless swarming flies fills the air around it. Where eyes ought to be, it has only a pair of luminous orbs that pulse between phosphorescent white and toxic green.", spells = { "Disintegrate", "Spirit Dispel" }, abilities = { "web_immobilize" } },

    -- Level 71
    { template_id = "fire_mage", name = "fire mage", level = 71, spawn_areas = { "Eye of V'Tull", "Glaes Caverns" }, roam_areas = { "Eye of V'Tull", "Glaes Caverns" }, family = "humanoid", body_type = "biped", hp = 240, hp_variance = 24, ds_ranged = 295, td = 345, armor_asg = 6, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "The fire mage isn't tall, standing no more than five feet, but her harrowing image is more than intimidating. Blackened skin of her face is framed with a wild mane of silvery hair, which lifts in the smoke and flames rising from the mage's robes like writhing serpents. Twin pits of fire glare out of the apparition's eye sockets, constantly sweeping her surroundings with maleficent intent.", attacks = { { type = "closed_fist" } }, spells = { "Firestorm", "Sleep", "Weapon Fire" }, abilities = { "fire_bolt", "earthen_fury_caster", "tremors", "elemental_barrier_430", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_targeting_425", "mass_blur_911", "prismatic_guard_905" } },

    -- Level 72
    { template_id = "krag_dweller", name = "krag dweller", level = 72, spawn_areas = { "Wehntoph", "Stormpeak" }, roam_areas = { "Wehntoph", "Stormpeak" }, family = "dweller", body_type = "biped", hp = 400, hp_variance = 40, ds_bolt = 229, td = 301, armor_asg = 20, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "The 'krag dweller' appears to be a cross between a troll and elemental rock. It towers over 8 feet tall with massive limbs. Jet black hairs grow between the plates of its brown scaly hide while long razor sharp fangs and claws provide the krag dweller with all the weapons it will ever need. Even darker than the blackest night, its eyes reveal the smouldering malice within.", attacks = { { type = "pound" } }, immune = { "dark catalyst 719", "implosion 720", "fire", "web 118" } },
    { template_id = "magna_vereri", name = "magna vereri", level = 72, spawn_areas = { "Den of Rot" }, roam_areas = { "Den of Rot" }, family = "ghost", classification = "corporeal_undead", body_type = "biped", hp = 400, hp_variance = 40, ds_melee = 320, ds_bolt = 319, td = 301, armor_asg = 8, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "A horrific magna vereri is the animated corpse of a woman, twisted into a perverse parody of beauty. Glowing white eyes glare out of a face whose cheeks are rouged with streaks of blood, and the lips are bloated and red around needle-like teeth. The obscene curvature of her body is at odds with her skeletal limbs, which are little more than bones clad in pale blue-grey corpseflesh. The vereri's movements are jerky and uneven as she totters around, driven by feral rage.", spells = { "Repel (Fear)" } },

    -- Level 73
    { template_id = "ilvari_sprite", base_template = "fire_sprite", name = "ilvari sprite", level = 73, spawn_areas = { "Red Forest" }, roam_areas = { "Red Forest" }, family = "fey", classification = "magical", body_type = "biped", hp = 240, hp_variance = 24, ds_ranged = 360, ds_bolt = 340, td = 338, armor_asg = 5, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "The subtle hourglass figure of this tiny offshoot of an elven female is all you can see due to a strange silvery aura covering her. Her face is the exception, for it shows through as a near picture perfect model of beauty. The only spoiler in the package is the strange look of madness in her shimmering silver eyes.", spells = { "Bone Shatter", "Repel (Fear)", "Wither", "Sympathy", "Spirit Dispel" }, abilities = { "lesser_shroud_120", "spirit_warding_i_101", "wall_of_force_140" } },
    { template_id = "storm_griffin", name = "storm griffin", level = 73, spawn_areas = { "Griffin's Keen", "Stormpeak" }, roam_areas = { "Griffin's Keen", "Stormpeak" }, family = "griffin", classification = "magical", body_type = "hybrid", hp = 400, hp_variance = 40, ds_melee = 264, ds_bolt = 263, td = 306, armor_asg = 12, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "The storm griffin is a magnificent beast, as if designed by the gods to embody fierce and graceful predation. Its front legs, forebody, wings, and head are those of a great eagle, complete with large powder-blue feathers and aquiline beak. The rear half of the creature's body is that of a powerful lion, with short, sandy blonde fur and a long feline tail. A tendril of electricity snakes across one outstreched claw as the storm griffin glares about with its piercing blue eyes.", attacks = { { type = "claw" }, { type = "impale" }, { type = "bite" } }, abilities = { "shock_burst", "call_wind", "sonic_wail" } },

    -- Level 74
    { template_id = "ilvari_pixie", name = "ilvari pixie", level = 74, spawn_areas = { "Red Forest" }, roam_areas = { "Red Forest" }, family = "fey", classification = "magical", body_type = "biped", hp = 240, hp_variance = 24, td = 333, armor_asg = 5, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "This smallish humanoid sports a pair of expressive sparkling eyes, lightly tanned skin, and a wide grin from ear to ear. Cute is too kind of a word for this caricature of elven descent. A faintly shimmering golden aura surrounds him.", attacks = { { type = "giant_bee_stinger" } }, spells = { "Major Acid", "Pain", "Elemental Dispel" }, abilities = { "tremors", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414" } },
    { template_id = "lesser_minotaur", name = "lesser minotaur", level = 74, spawn_areas = { "Wehntoph" }, roam_areas = { "Wehntoph" }, family = "minotaur", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 263, ds_ranged = 260, td = 297, armor_asg = 12, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "The lesser minotaur is an ugly, brutish looking beast. Taller than most average men, the minotaur has a bull-like appearance while his muscular body is humanoid with thick arms and broad shoulders. The lesser minotaur feet end in hooves that rattle the ground with every step. Despite his barbaric features, a great intelligence is reflected in the depths of his eyes and mannerisms.", attacks = { { type = "greataxe" }, { type = "waraxe" } }, abilities = { "charge_knockdown" } },

    -- Level 75
    { template_id = "greater_vruul", name = "greater vruul", level = 75, spawn_areas = { "The Broken Lands" }, roam_areas = { "The Broken Lands" }, family = "vruul", classification = "corporeal_undead", body_type = "biped", hp = 1000, hp_variance = 100, td = 281, preferred_stance = "guarded", stance_profile = "caster", description = "The 'greater vruul' has tough, leathery hide, as black as midnight. Bat-like wings sprout from its back, but they do not look large or strong enough to support its weight in flight. The vruul's claws are long, sharp and appear to be stained with the blood of many victims. Its eyes are eerie, solid green orbs that seem to glow with an inner power.", attacks = { { type = "claw" } }, spells = { "Bind", "Calm", "Frenzy", "Interference", "Silence", "Unbalance" }, abilities = { "bravery_211", "heroism_215", "lesser_shroud_120", "spell_shield_219", "spirit_defense_103", "spirit_shield_202", "spirit_warding_i_101" } },
    { template_id = "moulis", name = "moulis", level = 75, spawn_areas = { "Blighted Forest" }, roam_areas = { "Blighted Forest" }, family = "plant", classification = "magical", body_type = "hybrid", hp = 400, hp_variance = 40, ds_bolt = 211, td = 332, armor_asg = 12, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "Waving its myriad of oddly flexible, root-like appendages, the 'moulis' scuttles about its home area. It is not known what the moulis searches for, as observations have usually yielded a quick death for the observer, yet it is known that the moulis is an intelligent, lethal foe capable of commanding the forces of magic as well as a powerful physical attack. It appears to be nothing more than a writhing mass of tubers, roots and thin hair strands in various shades of brown--until a vicious attack springs from the center of the creature.", attacks = { { type = "attack" } }, spells = { "Cold Snap", "Immolation" }, abilities = { "call_wind", "elemental_bias_508", "strength_509" } },
    { template_id = "naisirc", name = "naisirc", level = 75, spawn_areas = { "The Rift" }, roam_areas = { "The Rift" }, family = "ghost", classification = "non_corporeal_undead", body_type = "hybrid", hp = 240, hp_variance = 24, ds_melee = 397, ds_bolt = 330, td = 330, armor_asg = 12, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "A dense cloud of flickering green pinpoints slowly revolves just above the ground, its mass spiked fitfully with outbursts of static electricity. In the next heartbeat, features, a tremendous torso, then massive arms knotted with thick muscles claim form from the hypnotic vapor. The naisirc moves lithely, belying its mighty proportions. As the naisirc stares at you, making a curious whispering noise, the spheres of glittering motes comprising its eyes send off crackles of furious viridian energy.", attacks = { { type = "charge_attack" }, { type = "ensnare_attack" } }, abilities = { "call_wind", "entangle", "elemental_targeting_425", "natural_colors_601", "mobility_618" } },
    { template_id = "treekin_sapling", name = "treekin sapling", level = 75, spawn_areas = { "Red Forest" }, roam_areas = { "Red Forest" }, family = "tree", classification = "magical", body_type = "hybrid", hp = 350, hp_variance = 35, td = 305, armor_asg = 12, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "Standing approximately five feet tall, this relatively mature sapling sways menacingly before you. Lambent yellow eyes and thick leg-shaped roots make it clear that this is no ordinary tree. Leaves cover the sapling from head to trunk, with two arm-shaped branches protruding from the canopy.", attacks = { { type = "branch_rake" }, { type = "root_lash" } }, abilities = { "trip" } },

    -- Level 76
    { template_id = "minotaur_warrior", name = "minotaur warrior", level = 76, spawn_areas = { "Wehntoph" }, roam_areas = { "Wehntoph" }, family = "minotaur", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 235, td = 294, armor_asg = 12, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "The minotaur warrior has the head of a bull while his muscular body is humanoid with thick arms and broad shoulders. Wearing a mish-mash of leather and chain armor, the fierce minotaur stomps about with hoofed feet brandishing its longsword at every possible foe.", attacks = { { type = "greataxe" }, { type = "moon_axe" } }, abilities = { "charge_knockdown" } },
    { template_id = "shrickhen", name = "shrickhen", level = 76, spawn_areas = { "Blighted Forest" }, roam_areas = { "Blighted Forest" }, family = "chimeric", classification = "corporeal_undead", body_type = "hybrid", hp = 300, hp_variance = 30, ds_bolt = 285, td = 344, armor_asg = 12, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "Seemingly cobbled together from leftover bodily parts, no two shrickhen are alike. One may have the lower body of a troll supporting the torso of a fire salamander from which a dark orc's arm extends on one side and a gremlin's arm extends on the other, all topped by a timberwolf's head. A second may have a mezic's leg, a coyote's leg, a pyrothag's arm, and a shan warrior's arm, each connected in almost the right place to the torso of a krolvin warfarer, with the entire grouping utilizing the one-eyed head of a cyclops for navigation. These hideous conglomerations definitely have two things in common: a total lack of fear and an insatiable need to consume flesh.", attacks = { { type = "bite" }, { type = "claw" } }, spells = { "Elemental Dispel" }, abilities = { "tremors", "elemental_defense_ii_406", "elemental_defense_iii_414" } },

    -- Level 77
    { template_id = "farlook", base_template = "magru", name = "farlook", level = 77, spawn_areas = { "Temple Wyneb" }, roam_areas = { "Temple Wyneb" }, family = "globoid", body_type = "hybrid", ds_melee = 220, td = 317, preferred_stance = "guarded", stance_profile = "caster", description = "Torrents of spiritual magic dance around the farlook in a vivid display of black and white wisps. A soft liquid membrane is covered with a thickened skin that covers three-fourths of sphere-shape. A large, iris takes up the remaining quarter, which can be protected by a folded layer of skin just just above it. A sick goo constantly drips from the severed nerve ending jutting out of the back of the farlook. Crimson energy ripples emanate from the bottom of the farlook, causing it to bob up and down a few inches off the ground.", spells = { "Hand of Tonis" }, abilities = { "shock_burst", "tremors", "call_wind", "tail_spike_volley", "earthen_fury_caster" } },
    { template_id = "raving_lunatic", name = "raving lunatic", level = 77, spawn_areas = { "The Rift" }, roam_areas = { "The Rift" }, family = "humanoid", classification = "extra_planar", body_type = "biped", hp = 300, hp_variance = 30, ds_ranged = 346, ds_bolt = 359, td = 330, armor_asg = 8, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "Perhaps driven mad by the shifting world around her, the raving lunatic babbles and chatters to herself, sometimes gleefully, sometimes angrily. A disgustingly corpulent humanoid, her rolls of pink flesh bounce and quiver as the raving lunatic staggers from area to area, not comprehending her surroundings. Clear spittle drools from her open mouth, and her unblinking eyes dart wildly about in unfocused confusion. She is a totally unpredictable foe.", attacks = { { type = "short_sword" } } },

    -- Level 78
    { template_id = "dhu_goleras", name = "dhu goleras", level = 78, spawn_areas = { "Blighted Forest" }, roam_areas = { "Blighted Forest" }, family = "goleras", classification = "magical", body_type = "hybrid", hp = 240, hp_variance = 24, ds_bolt = 292, td = 365, armor_asg = 10, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "Dull, mottled, grey skin covers the dhu goleras's stubby, wrinkled torso. The arms appear twice as long as they should be, ending in long, twig-like fingers. The legs are the opposite. Short and misshapen, they have three knees each, giving the dhu goleras a peculiar, hobbling gait, yet with incredible quickness. Huge, lidless, moon-shaped eyes with white irises bulge from a bony cranium atop a long, thin, rubbery neck. Green ichor drips from around the eyes, running down the sunken cheeks. The dhu goleras extends his long white tongue and licks off what ichor he can reach, consuming it with relish.", attacks = { { type = "dagger" } }, spells = { "Balefire", "Bind", "Blood Burst", "Calm", "Corrupt Essence", "Curse", "Dark Catalyst", "Disintegrate", "Limb Disruption" } },
    { template_id = "minotaur_magus", name = "minotaur magus", level = 78, spawn_areas = { "Wehntoph" }, roam_areas = { "Wehntoph" }, family = "minotaur", body_type = "biped", hp = 250, hp_variance = 25, td = 317, armor_asg = 11, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "The minotaur magus is an ugly, brutish looking beast. Taller than most average men, the minotaur has a bull-like appearance while his muscular body is humanoid with thick arms and broad shoulders. The minotaur magi feet end in hooves that rattle the ground with every step. Despite his barbaric features, a great intelligence is reflected in the depths of his eyes and mannerisms.", attacks = { { type = "runestaff" } }, spells = { "Divine Fury" }, abilities = { "flame_aura", "heroism_215", "spirit_strike", "spell_shield_219", "spirit_defense_103", "spirit_shield_202", "spirit_warding_i_101" } },
    { template_id = "seraceris", name = "seraceris", level = 78, spawn_areas = { "The Rift" }, roam_areas = { "The Rift" }, family = "ghost", classification = "non_corporeal_undead", body_type = "biped", hp = 240, hp_variance = 24, ds_melee = 311, ds_bolt = 313, td = 365, udf = 500, armor_asg = 2, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "The seraceris stands tall and slender, its body appearing almost two-dimensional as it moves. In the creature's angular face sit two pools of blinding white light, and rays extend from the eye sockets in stark beams which arc around it in a nightmarish aurora. Waves of energy shed by the malign magic permeating the seraceris lift its ragged robes in a jagged halo, echoing its long, gnarled fingers as they dance in a constant blur of spell-summoning.", attacks = { { type = "claw_attack" } }, spells = { "Holding Song", "Vibration Chant", "Curse", "Evil Eye", "Disintegrate" }, abilities = { "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "lesser_shroud_120", "wall_of_force_140" } },

    -- Level 79
    { template_id = "crackling_lightning_fiend", base_template = "cold_guardian", name = "crackling lightning fiend", level = 79, spawn_areas = { "Stormpeak" }, roam_areas = { "Stormpeak" }, family = "elemental", body_type = "hybrid", hp = 260, hp_variance = 26, td = 382, armor_asg = 6, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "Flashes of brilliant azure flicker and fade within the lightning fiend's mesmerizing shape, an amorphous form woven from threads of wildly dancing electricity. At times, the elemental takes the shape of a vaguely humanoid figure, its translucent helm graced by two wildly twisting horns. Arcing arteries of lightning leap from the heart of the fiend to shimmer up nearby surfaces. The lightning fiend is medium in size and about six feet high in its current state.", spells = { "Lightning Torrent(?)" }, abilities = { "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414" } },

    -- Level 80
    { template_id = "vvrael_witch", base_template = "athletic_dark_eyed_incubus", name = "vvrael witch", level = 80, spawn_areas = { "The Rift" }, roam_areas = { "The Rift" }, family = "vvrael", classification = "extra_planar", body_type = "biped", hp = 220, hp_variance = 22, udf = 600, armor_asg = 1, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "The 'Vvrael witch' rises from the ground in a pillar of shadow, tall and slim, the outline of her perfect form frayed by a strange atmospheric disturbance. Her face is a vision of beauty. However, darkness fills her features like a secret biding in her glance, lending her visage an indistinct appearance. Her eyes are dark and wide, framed with fringes of long lashes, and in the depths of those expressive wells there flickers highlights of energy. Or perhaps they are coals of hatred waiting to be unearthed. The witch's hands move constantly, her long fingers and elegant nails making constant motions as if they have manic agendas of their own.", spells = { "Elemental Dispel" }, abilities = { "acid_spray", "earthen_fury_caster", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_targeting_425", "elemental_barrier_430", "elemental_bias_508", "mass_blur_911" } },

    -- Level 81
    { template_id = "csetairi", name = "csetairi", level = 81, spawn_areas = { "The Rift" }, roam_areas = { "The Rift" }, family = "csetairi", classification = "magical", body_type = "hybrid", hp = 240, hp_variance = 24, ds_ranged = 334, td = 362, armor_asg = 5, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "The csetairi has several humanoid features, appearing as a shapely woman with long, silky, black hair. However, the differences are readily apparent. Instead of legs, she has a long, thick, coiled tail, and her locomotion is definitely snakelike. Four arms sprout from her chest, and long, pointed fangs extend down below her upper lip. Her slitted, olive green eyes scan the area rapidly, looking for potential victims.", attacks = { { type = "scimitar" } }, spells = { "Bind", "Frenzy" }, abilities = { "fire_bolt", "web_immobilize", "bravery_211", "heroism_215", "spirit_warding_i_101", "spirit_defense_103", "lesser_shroud_120", "spirit_shield_202", "spell_shield_219" } },
    { template_id = "greater_skayl", name = "greater skayl", level = 81, spawn_areas = { "Eye of V'Tull" }, roam_areas = { "Eye of V'Tull" }, family = "elemental", classification = "magical", body_type = "hybrid", hp = 300, hp_variance = 30, td = 379, armor_asg = 16, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "Flame suddenly hisses and spits from thin air, which shimmers in the resulting smoke like reflective crystal. Then abruptly, the air roils and begins to take on form. In mere heartbeats, it becomes obvious that the transparent bubble of conflagration is a sentient being. The greater skayl opens its gaping maw of fire and bellows a malign growl that is more felt than heard. In the next instant, the greater skayl melts down then reforms a short distance away, leaving a drift of smoke in its wake like a fraying shadow.", attacks = { { type = "pound" }, { type = "ensnare" } }, spells = { "Balefire" }, abilities = { "earthen_fury_caster", "elemental_bias_508", "strength_509", "mass_blur_911" } },
    { template_id = "stooped_titan_stormcaller", base_template = "arctic_titan", name = "stooped titan stormcaller", level = 81, spawn_areas = { "Stormpeak" }, roam_areas = { "Stormpeak" }, family = "giant", body_type = "biped", hp = 400, hp_variance = 40, td = 381, armor_asg = 2, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "The power of the storm cannot be contained in the titan stormcaller's body. Jagged bolts of electricity arc up from under her skin and crackle down her limbs, seemingly causing her no pain during their passage. Despite her towering height, the stormcaller's stooped shoulders and spindly limbs make her look less imposing. Her features are plain and unlovely. The titan stormcaller is huge in size and about twelve feet high in his current state.", abilities = { "elemental_defense_iii_414", "elemental_barrier_430", "mass_blur_911" } },

    -- Level 82
    { template_id = "bent_being", name = "bent being", level = 82, spawn_areas = { "Old Ta'Faendryl" }, roam_areas = { "Old Ta'Faendryl" }, family = "chimeric", body_type = "biped", hp = 300, hp_variance = 30, td = 390, preferred_stance = "forward", stance_profile = "berserker", description = "The bent being is a twisted amalgamation of flesh and other, less mentionable things. Stark white hair grows in random patches from the being's sickly green skin, especially around its face. The bent being has over-sized ears that look comical on an otherwise intimidating foe. Thick legs sprout from the being's midsection like tree trunks, ending in gigantic feet that could fit in no boot made for civilized creatures.", attacks = { { type = "stomp" } }, abilities = { "shock_burst", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "mass_blur_911", "prismatic_guard_905" } },
    { template_id = "caedera", name = "caedera", level = 82, spawn_areas = { "The Rift" }, roam_areas = { "The Rift" }, family = "worm", classification = "magical", body_type = "ophidian", hp = 600, hp_variance = 60, ds_ranged = 321, td = 345, armor_asg = 12, armor_natural = true, preferred_stance = "offensive", stance_profile = "skirmisher", description = "The caedera looms malevolently over its prey. Yellow ichor drips from its slavering jaws as its massive head lolls blindly from side to side. Keen senses of smell and sound lead this gargantuan worm to the location of its next meal. Its segmented body contracts and expands powerfully, allowing the beast to burrow through rock and soil with the same ease that other creatures move through the air. Each segment is dark orange with mottled brown spots, though the rings where the segments join are a charcoal grey.", attacks = { { type = "bite" }, { type = "charge_attack" }, { type = "ensnare_attack" } }, abilities = { "hide" } },
    { template_id = "earth_elemental", name = "earth elemental", level = 82, spawn_areas = { "Thanatoph" }, roam_areas = { "Thanatoph" }, family = "elemental", classification = "extra_planar", body_type = "hybrid", hp = 400, hp_variance = 40, td = 375, armor_asg = 20, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "Massive and thick, with broad shoulders but no apparent head, the earth elemental appears to be a composite of the earth itself. A large, craggy maw in the middle of the elemental's chest appears to be the creature's mouth, and the earth elemental's huge feet and giant-sized fists look like they would pulverize flesh without much effort at all.", attacks = { { type = "pound_attack" } } },
    { template_id = "gnarled_being", name = "gnarled being", level = 82, spawn_areas = { "Old Ta'Faendryl" }, roam_areas = { "Old Ta'Faendryl" }, family = "chimeric", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 594, td = 390, armor_asg = 12, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "The gnarled being is a twisted amalgamation of flesh and other, less mentionable things. Tusks and horns grow from its head in an impressive array of weaponry. The tough, pale yellow skin of the being looks burnt and scorched in places, but this doesn't seem to bother it. The gnarled being's twisted hands and feet end with wicked, razor-sharp claws that refuse to shine in the light.", attacks = { { type = "claw" }, { type = "impale" } }, abilities = { "hide" } },
    { template_id = "stooped_being", name = "stooped being", level = 82, spawn_areas = { "Old Ta'Faendryl" }, roam_areas = { "Old Ta'Faendryl" }, family = "chimeric", body_type = "biped", hp = 300, hp_variance = 30, td = 390, armor_asg = 12, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "The stooped being is a twisted amalgamation of flesh and other, less mentionable things. Skin that is sickly green gives way to an odd, jelly-like substance that covers most of the being's torso. A few extra, stunted arms and short, deformed tentacles protrude from the shoulders and back of the stooped being. The most terrifying part of this abomination's anatomy is the second head that sits in its chest, complete with a mouth, nose, and several dozen eyes.", attacks = { { type = "claw" }, { type = "bite" } } },
    { template_id = "twisted_being", name = "twisted being", level = 82, spawn_areas = { "Old Ta'Faendryl" }, roam_areas = { "Old Ta'Faendryl" }, family = "chimeric", body_type = "biped", hp = 300, hp_variance = 30, td = 390, preferred_stance = "forward", stance_profile = "berserker", description = "The twisted being is a twisted amalgamation of flesh and other, less mentionable things. The chalky white skin of this being is rough and pebbly, similar to a reptile's. Two beady black eyes peer out from a snake-shaped head that is topped with a twisted, spiked crest which runs all the way down the being's spine and along its whip-like tail. Row upon row of deadly, razor-sharp teeth fill the being's mouth, and saliva drips from its thick purple tongue.", attacks = { { type = "bite" }, { type = "claw" } }, abilities = { "spirit_defense_103", "spirit_warding_i_101", "lesser_shroud_120", "prismatic_guard_905", "mass_blur_911" } },

    -- Level 83
    { template_id = "lesser_construct", name = "lesser construct", level = 83, spawn_areas = { "Old Ta'Faendryl" }, roam_areas = { "Old Ta'Faendryl" }, family = "golem", classification = "magical", body_type = "biped", hp = 500, hp_variance = 50, ds_melee = 267, armor_asg = 19, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "The white granite-like features of the lesser construct hold no hints of the giant creature's intentions or motivations. Its alabaster skin made more of the hardest rock than any living tissue makes the construct a formidable opponent for any who dare to trifle with it. Massing more than ten giantmen, it is a a mountain of rock when in motion and very little, man or animal can oppose its desired path of travel once it is in motion.", attacks = { { type = "flail" }, { type = "stomp" } } },
    { template_id = "titan_tempest_tyrant", base_template = "stooped_titan_stormcaller", name = "titan tempest tyrant", level = 83, spawn_areas = { "Stormpeak" }, roam_areas = { "Stormpeak" }, family = "giant", body_type = "biped", hp = 400, hp_variance = 40, td = 347, armor_asg = 12, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "Though powerfully muscled, the tempest tyrant is so tall and long of limb that she looks well-proportioned, even agile. Ritual scars like lightning bolts fork down her immense arms, and matching tattoos in metallic ink gleam electric blue from her severe face. They curve around each eye and fan out onto her hollow cheeks, lending her unforgiving features an alien cast. The tempest tyrant is huge in size and about thirteen feet high in her current state.", abilities = { "spirit_warding_i_101", "spirit_barrier_102", "spirit_defense_103", "elemental_defense_i_401", "elemental_defense_ii_406", "blink_1215" } },
    { template_id = "treekin_druid", name = "treekin druid", level = 83, spawn_areas = { "Red Forest" }, roam_areas = { "Red Forest" }, family = "tree", classification = "magical", body_type = "hybrid", hp = 400, hp_variance = 40, ds_bolt = 217, td = 379, armor_asg = 16, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "Standing approximately eight feet tall, the treekin druid glares at you with malevolent intent. Lambent yellow eyes and thick leg-shaped roots make it clear that this is no ordinary tree. Leaves cover the druid from head to trunk, with two arm-shaped branches protruding from the canopy. A long mossy beard dangles below a crooked knothole under the eyes, giving gnarled look to an already imposing foe.", attacks = { { type = "pound" }, { type = "root_lash" }, { type = "root_slam" } }, spells = { "Hurl Boulder", "Searing Light", "Spirit Dispel", "Phoen's Strength" }, abilities = { "gas_cloud", "tail_spike_volley", "natural_colors_601", "resist_elements_602" } },

    -- Level 84
    { template_id = "greater_krynch", name = "greater krynch", level = 84, spawn_areas = { "Thanatoph" }, roam_areas = { "Thanatoph" }, family = "krynch", body_type = "biped", hp = 300, hp_variance = 30, ds_bolt = 224, td = 345, armor_asg = 20, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "Veins of mica and quartz crystal run along and through the towering krynch's barrel chest and thick, powerful limbs, causing it to shimmer in even the dimmest light. A crown of rough rock and crystal spikes protrude from the top of its otherwise perfectly spherical head, adding to the creature's powerful stature. Its mouth is fixed in a perpetual scowl, and glossy black eyes glare at you with malevolent intensity.", attacks = { { type = "pound_attack" } } },
    { template_id = "gremlock", name = "gremlock", level = 84, spawn_areas = { "Old Ta'Faendryl" }, roam_areas = { "Old Ta'Faendryl" }, family = "gremlin", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 431, ds_bolt = 302, td = 361, armor_asg = 8, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "The gremlock is larger than her relative, the gremlin, stretching five to six feet in height. The back hunched over from her time spent in the shadows stalking her prey, her actual height cannot be determined accurately. Tufts of dirty fur form a straggly mane around the savage looking face. Her long bulky arms tipped with massive claws only add to the deformity of the gremlock with her razor-sharp maw and potentially fatal, hungry glare.", attacks = { { type = "claw" } } },
    { template_id = "lich_qynarj", base_template = "shrickhen", name = "lich qyn'arj", level = 84, spawn_areas = { "Old Ta'Faendryl" }, roam_areas = { "Old Ta'Faendryl" }, family = "reptilian", classification = "corporeal_undead", body_type = "hybrid", td = 391, armor_asg = 6, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "The qyn'arj is a creature of legend, a massive serpent held aloft on brightly colored wings. But the lich qyn'arj before you has been animated by some means. The qyn'arj's body seems to hover there without the need to beat its rotting and mottled wings. Decaying flesh covers its body, but the head is completely skeletal and polished to the fine white of bleached bone. Swirling red pinpoints float where eyes used to be, and dagger sharp teeth can be seen inside its maw.", attacks = { { type = "bite" } }, spells = { "Unbalance" }, abilities = { "cold_flare", "web_immobilize", "lesser_shroud_120", "spirit_shield_202" } },
    { template_id = "steam_dervish", name = "steam dervish", level = 84, spawn_areas = { "Eye of V'Tull" }, roam_areas = { "Eye of V'Tull" }, family = "humanoid", classification = "magical", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 324, ds_bolt = 290, td = 370, armor_asg = 16, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "This wiry humanoid resembles a gaunt human with badly blistered and burnt skin. In the place of eyes, two steaming holes glower with malevolent intent. A persistent cloud of steam emanates from the steam dervish, extending an aura of oppressive humidity around her.", attacks = { { type = "longsword" } }, abilities = { "hamstring" } },
    { template_id = "vvrael_warlock", name = "vvrael warlock", level = 84, spawn_areas = { "The Rift" }, roam_areas = { "The Rift" }, family = "vvrael", classification = "extra_planar", body_type = "biped", hp = 240, hp_variance = 24, ds_melee = 420, ds_ranged = 328, armor_asg = 2, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "The 'Vvrael warlocks figure is tall and thin, with stark proportions that call to mind sharp, unforgiving angles. His features are stoic, however the eyes held in that pale, rigidly handsome face are full of fury and malignant intent. The creature seems to move in slow motion, each gesture full of drama and elegance. But the appearance of languid grace is insubstantial. Experience soon dispells this illusion and reveals the true nature of this enemy, whose movements are both lightning quick and deadly.", attacks = { { type = "whip" } }, spells = { "Balefire", "Corrupt Essence", "Curse", "Elemental Blast", "Evil Eye", "Dark Catalyst", "Torment", "Elemental Dispel" }, abilities = { "spirit_strike", "bravery_211", "spirit_warding_i_101", "lesser_shroud_120", "wall_of_force_140", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_barrier_430" } },

    -- Level 85
    { template_id = "firebird", name = "firebird", level = 85, spawn_areas = { "The F'Eyrie" }, roam_areas = { "The F'Eyrie" }, family = "bird", classification = "magical", body_type = "avian", hp = 400, hp_variance = 40, td = 359, armor_asg = 12, armor_natural = true, preferred_stance = "offensive", stance_profile = "skirmisher", description = "Smoldering black eyes and a sharp golden beak display the fury of the firebird. A golden crest of feathers adorn the head of this large but nimble avian that continues down its long craning neck, transitioning to orange around its sleek body, then deep red along its narrow legs that end in wickedly sharp black talons. Flames dance from the firebird's wide arcing wings that leave a trail with its long tail feathers in its wake.", attacks = { { type = "claw_attack" }, { type = "bite_attack" }, { type = "impale_attack" } }, abilities = { "fire_bolt", "sonic_wail" } },
    { template_id = "haggard_veiki_herald", base_template = "titan_tempest_tyrant", name = "haggard veiki herald", level = 85, spawn_areas = { "Stormpeak" }, roam_areas = { "Stormpeak" }, family = "giant", body_type = "biped", hp = 400, hp_variance = 40, td = 415, armor_asg = 8, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "Power rumbles and thrums through the limbs of the Veiki herald. That barely contained might and the intensity of his devotion have colluded to burn the meat from his bones, leaving him skeletally thin. The hollows of his face are deep and haunted, the crags cast in deep shadow by the flashes of brilliant azure that flicker and fade within his mesmerizing stare. The herald's hair is brittle and blanched, starkly pale against his sun-darkened skin. The Veiki herald is huge in size and about thirteen feet high in his current state.", spells = { "Templar's Verdict" }, abilities = { "mantle_of_faith_1601" } },

    -- Level 86
    { template_id = "aivren", name = "aivren", level = 86, spawn_areas = { "The Rift" }, roam_areas = { "The Rift" }, family = "aivren", body_type = "avian", hp = 300, hp_variance = 30, ds_melee = 400, ds_bolt = 335, td = 373, armor_asg = 8, armor_natural = false, preferred_stance = "offensive", stance_profile = "skirmisher", description = "Leathery, ochre wings extending as wide as a giantman is tall, the 'aivren' wheels and swoops with amazing dexterity. The aivren flies low over the landscape, snapping up anything remotely edible in its long, pointed beak or sharp, descending claws. Charcoal grey on the underbelly and a dusky ochre on the back, its speed often surprises its foes, allowing the aivren to strike the death blow before the opponent can react.", attacks = { { type = "bite_attack" }, { type = "claw_attack" } } },
    { template_id = "festering_taint", name = "festering taint", level = 86, spawn_areas = { "Old Ta'Faendryl" }, roam_areas = { "Old Ta'Faendryl" }, family = "humanoid", body_type = "biped", hp = 240, hp_variance = 24, ds_melee = 403, ds_ranged = 291, td = 380, armor_asg = 8, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "The 'festering taint' is a putrescent collection of rotting flesh and disease. The gender of the taint is impossible to make out due to the scabs and boils which cover its skin, oozing out disgustingly. Black and yellow rotting teeth are displayed in a mouth that is unnaturally wide underneath two black eyes that stare out with a frightening spark of intelligence. No nose or ears are visible on the festering taint, but it has a mop of greasy, filthy black hair that sprouts from the top of its head.", attacks = { { type = "claw" } }, spells = { "Curse", "Dark Catalyst", "Disease", "Disintegrate", "Mind Jolt", "Unbalance", "Grasp of the Grave" }, abilities = { "flame_aura", "tremors", "lesser_shroud_120", "spirit_defense_103", "spirit_warding_i_101", "wall_of_force_140" } },
    { template_id = "illoke_elder", name = "illoke elder", level = 86, spawn_areas = { "Thanatoph" }, roam_areas = { "Thanatoph" }, family = "giant", body_type = "biped", hp = 600, hp_variance = 60, ds_melee = 305, ds_ranged = 309, ds_bolt = 202, armor_asg = 16, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "The enormous form of the 'Illoke elder' occupies a large section of the area, over twenty feet at his full height. He carries himself with an air of confident superiority, casting a hate-filled gaze around him. Thick and rough grey skin covers him from head to toe, providing protection against all but the strongest of blows. A deep crimson symbol of Illoke is chiseled into his forehead, bathing his face in a lurid illumination.", attacks = { { type = "stomp_attack" }, { type = "sledgehammer" }, { type = "stalagmite" }, { type = "rock_hurled" } }, spells = { "Stone Fist", "Elemental Disjunction" }, abilities = { "tremors", "tail_spike_volley" } },

    -- Level 87
    { template_id = "ash_guardian", name = "ash guardian", level = 87, spawn_areas = { "The F'Eyrie" }, roam_areas = { "The F'Eyrie" }, family = "elemental", body_type = "biped", hp = 240, hp_variance = 24, td = 397, armor_asg = 16, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "Distinct features are difficult to determine as clouds of ash obscure the form of the ash guardian. What is visible is a towering humanoid shadow that drifts through the ash clouds.", attacks = { { type = "falchion" } }, abilities = { "taunt" } },
    { template_id = "necare", name = "n'ecare", level = 87, spawn_areas = { "The Rift" }, roam_areas = { "The Rift" }, family = "n_ecare", classification = "corporeal_undead", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 330, td = 359, preferred_stance = "forward", stance_profile = "berserker", description = "Shadows suddenly converge, revealing the skulking form of a creature with horribly elongated extremities and twisted anatomy. The 'n'ecare's' movements are as fleet as a hare, rendering him difficult to see clearly, and his spidery fingers skitter constantly, as if the n'ecare was using them to taste the air around him. From the dark pools of gloom beneath his cracked brows, the n'ecare's eyes glitter in fanatical mirth, made all the more terrible by the rotting maw of his grin.", attacks = { { type = "falchion" }, { type = "mace" } }, abilities = { "tackle", "trip" } },

    -- Level 88
    { template_id = "greater_earth_elemental", name = "greater earth elemental", level = 88, spawn_areas = { "Thanatoph" }, roam_areas = { "Thanatoph" }, family = "elemental", classification = "extra_planar", body_type = "hybrid", hp = 500, hp_variance = 50, ds_melee = 119, td = 332, armor_asg = 20, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "Massive and thick, with broad shoulders but no apparent head, the earth elemental appears to be a composite of the earth itself. A large, craggy maw in the middle of the elemental's chest appears to be the creature's mouth, and the earth elemental's huge feet and giant-sized fists look like they would pulverize flesh without much effort at all. Greater earth elementals have DFRedux which will reduce the damage factors of weapons, including bolt spells, by 30% for AS-based attacks. This is in addition to their natural full plate equivalent armor.", attacks = { { type = "pound_attack" }, { type = "thrown_rock" } } },

    -- Level 89
    { template_id = "illoke_jarl", name = "illoke jarl", level = 89, spawn_areas = { "Thanatoph" }, roam_areas = { "Thanatoph" }, family = "giant", body_type = "biped", hp = 600, hp_variance = 60, ds_melee = 270, td = 373, armor_asg = 16, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "The hulking frame of the Illoke jarl towers high overhead, ready to obliterate any who would intrude upon his territory. Craggy, deep grey skin sheathes him in a natural armor, with little hindrance to his movements. A pair of piercing black eyes stare out with contempt, barely distinguishable against his dark complexion. In contrast, a shimmering crimson symbol of Illoke is chiseled deep into his forehead, radiating a dull red glow.", attacks = { { type = "fist" }, { type = "hammer" } }, spells = { "Divine Strike" }, abilities = { "spirit_strike", "lesser_shroud_120" } },
    { template_id = "ithzir_scout", name = "ithzir scout", level = 89, spawn_areas = { "Old Ta'Faendryl" }, roam_areas = { "Old Ta'Faendryl" }, family = "ithzir", classification = "extra_planar", body_type = "biped", hp = 300, hp_variance = 30, ds_ranged = 343, ds_bolt = 392, td = 368, armor_asg = 12, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "Wide, pupil-less green eyes peer about, quickly assessing both threats and terrain. The Ithzir scout stalks in a fluid, half-crouch that is as graceful as it is lightning fast, his whole demeanor underscoring his menace and obvious intelligence. The Ithzir scout is slightly taller than a human, and while his humanoid form is similar to scores of other races, the hairless, blue-skinned body is nonetheless alien in its appearance. The scout wears a charcoal grey tunic with no apparent identifiers of his station.", attacks = { { type = "broadsword" } }, abilities = { "trip" } },

    -- Level 90
    { template_id = "blazing_red_phoenix", name = "blazing red phoenix", level = 90, spawn_areas = { "The F'Eyrie" }, roam_areas = { "The F'Eyrie" }, family = "elemental", classification = "magical", body_type = "avian", hp = 320, hp_variance = 32, ds_ranged = 293, td = 411, armor_asg = 12, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "Composed entirely of elemental flame, the majestic blazing red phoenix resembles a deadly bird of prey, with a short hooked beak, a compact muscular frame, wide wingspan, and sharp talons. Its unearthly form is a constant wreathing of elemental fire that is at once blinding as it is scalding.", attacks = { { type = "claw_attack" }, { type = "bite_attack" } }, spells = { "Immolation", "Firestorm" }, abilities = { "fire_bolt", "tremors" } },

    -- Level 91
    { template_id = "ithzir_initiate", name = "ithzir initiate", level = 91, spawn_areas = { "Old Ta'Faendryl" }, roam_areas = { "Old Ta'Faendryl" }, family = "ithzir", classification = "extra_planar", body_type = "biped", hp = 240, hp_variance = 24, ds_bolt = 387, td = 395, armor_asg = 6, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "The Ithzir initiate carries herself with a humble bearing, her arresting, pupil-less green eyes taking in her surroundings with confidence and surety. Even when battle rages around her, each movement of the initiate seems eerily effortless and calm. The Ithzir initiate is slightly taller than a human, and while her humanoid form is similar to scores of other races, the hairless, blue-skinned body is nonetheless alien in its appearance. The initiate wears a crisply-cut, blue tunic with a green palm-print emblazoned on the right breast.", attacks = { { type = "quarterstaff" } }, spells = { "Bind", "Divine Fury", "Divine Wrath", "Fervent Reproach", "Mass Interference" }, abilities = { "flame_aura", "web_immobilize", "heroism_215", "spirit_strike", "lesser_shroud_120", "spell_shield_219", "spirit_defense_103", "spirit_shield_202", "spirit_warding_i_101", "wall_of_force_140" } },
    { template_id = "lost_soul", name = "lost soul", level = 91, spawn_areas = { "The Rift" }, roam_areas = { "The Rift" }, family = "ghost", classification = "non_corporeal_undead", body_type = "biped", hp = 240, hp_variance = 24, ds_melee = 420, td = 417, armor_asg = 8, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "The lost soul appears as the flickering shade of a normal humanoid, his face contorted into a soundless, agonized scream. His flesh slowly melts off his frame, bubbling, dripping to the ground, and his clothing turns into rags, dropping off in shreds, until nothing is left but a skeleton with hate-filled red eyes. Slowly the flesh reforms, the clothing regains its form, all in nearly reverse order, until the lost soul is once again whole. Then, horribly, he begins to deteriorate again.", attacks = { { type = "scythe" } }, spells = { "Elemental Dispel" }, abilities = { "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_barrier_430" } },

    -- Level 92
    { template_id = "ithzir_janissary", name = "ithzir janissary", level = 92, spawn_areas = { "Old Ta'Faendryl" }, roam_areas = { "Old Ta'Faendryl" }, family = "ithzir", classification = "extra_planar", body_type = "biped", hp = 300, hp_variance = 30, ds_ranged = 289, ds_bolt = 249, td = 376, armor_asg = 16, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "The Ithzir janissary's movements are both aggressive and graceful, his muscular, lithe form the envy of any acrobat or student of the martial arts. Wide, upward-slanted, green eyes take in his surroundings with an easy confidence, as if the fate of any opponent is not a matter of chance, only of time. The Ithzir janissary is a head taller than a human, and while his humanoid form is similar to scores of other races, the hairless, blue-skinned body is nonetheless alien in its appearance. The janissary wears a crisply-cut silvery blue tunic emblazoned with a feline silhouette on the right breast.", attacks = { { type = "longsword" }, { type = "military_fork" }, { type = "mace" } }, abilities = { "disarm_weapon", "trip" } },
    { template_id = "water_elemental", base_template = "water_witch", name = "water elemental", level = 92, spawn_areas = { "Ruined Temple" }, roam_areas = { "Ruined Temple" }, family = "elemental", classification = "extra_planar", body_type = "hybrid", ds_melee = 367, td = 409, armor_asg = 10, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "The water elemental's upper body is that of a humanoid, while its lower body forms a turbulent, watery vortex. The facial features of the elemental creature are vague and shifting, rippling with every contortion of its face. Sloshing and splashing noises accompany each movement of the water elemental, along with an odd gurgling.", attacks = { { type = "pound" } }, abilities = { "elemental_barrier_430", "elemental_defense_ii_406", "elemental_defense_iii_414" } },

    -- Level 93
    { template_id = "ithzir_herald", base_template = "grutik_shaman", name = "ithzir herald", level = 93, spawn_areas = { "Old Ta'Faendryl" }, roam_areas = { "Old Ta'Faendryl" }, family = "ithzir", classification = "extra_planar", body_type = "biped", ds_bolt = 386, td = 380, armor_asg = 9, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "A trio of black tattooed stripes run from center of the Ithzir herald's forehead and over the crown of his bald, blue-skinned head. The Ithzir herald is slightly taller than a human, and while his humanoid form is similar to scores of other races, the hairless, blue body is nonetheless alien in its appearance. The herald wears a fine silvery-blue tunic crossed with a green tabard.", attacks = { { type = "falchion" } }, spells = { "Lullabye", "Song of Depression", "Song of Rage", "Song of Sonic Disruption", "Vibration Chant", "Mass Calm" }, abilities = { "tremors", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_barrier_430" } },
    { template_id = "vaespilon", name = "vaespilon", level = 93, spawn_areas = { "The Rift" }, roam_areas = { "The Rift" }, family = "humanoid", classification = "corporeal_undead", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 400, td = 436, armor_asg = 2, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "The vaespilon's features are so terribly deformed by death's ravages, her expression is one of almost comical surprise, until her smile widens into a grin that is a study in terror. The skin covering the walking corpse is mottled and stretched unevenly over the bones, and the surface ripples and bulges as if putrescence is bubbling underneath. The vaespilon hisses in glee as she moves, a wave of stench preceding her like an invisible assailant.", spells = { "Implosion" }, abilities = { "spirit_strike", "bravery_211", "spirit_warding_i_101", "spirit_defense_103", "lesser_shroud_120", "wall_of_force_140", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_barrier_430", "puncture_resistant" } },

    -- Level 94
    { template_id = "triton_dissembler", base_template = "gnoll_ranger", name = "triton dissembler", level = 94, spawn_areas = { "Ruined Temple" }, roam_areas = { "Ruined Temple" }, family = "triton", body_type = "biped", ds_melee = 291, preferred_stance = "guarded", stance_profile = "ranged", description = "Weight carefully balanced upon her massive tail, the triton dissembler walks rigidly upright, moving with self-absorbed elegance. Luminous dark blue eyes are set deeply in the sockets of her fine-boned head where delicate, fleshy lips curve into an unpleasant smile. The dissembler's long, translucently webbed hands bear curved claws, carefully filed to tapered points and painted with gold lacquer. This pretense to arrogant refinement belies the feverishly clammy sweat covering the creature's slick, sea green hide.", spells = { "Empathic Assault", "Disintegrate", "Implosion" }, abilities = { "spirit_defense_103", "spirit_warding_i_101" } },
    { template_id = "triton_warlock", name = "triton warlock", level = 94, spawn_areas = { "Atoll" }, roam_areas = { "Atoll" }, family = "triton", body_type = "biped", hp = 240, hp_variance = 24, ds_melee = 530, td = 446, udf = 615, armor_asg = 6, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "The amphibian visage of a triton warlock gazes out beneath a frayed dark blue robe, her sun-cracked lips curled back into a sneer as she observes the area with slitted, sickly yellow eyes. Her emaciated form leans backwards, leaving her sinewy arms exposed to the elements as they grip tightly to her staff, her green-fleshed knuckles branded in rough runes. Her head rotates at the most minute of changes, nostrils flaring as she murmurs indecipherable incantations to herself in preparation of the unknown.", attacks = { { type = "runestaff" } }, spells = { "Balefire", "Disintegrate", "Mind Jolt", "Torment", "Dark Catalyst" }, abilities = { "spirit_warding_i_101", "spirit_defense_103", "lesser_shroud_120", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414" } },

    -- Level 95
    { template_id = "huge_air_elemental", base_template = "water_elemental", name = "huge air elemental", level = 95, spawn_areas = { "Elemental Confluence" }, roam_areas = { "Elemental Confluence" }, family = "elemental", classification = "extra_planar", body_type = "hybrid", ds_bolt = 312, td = 410, armor_asg = 10, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "The air elemental is a vaguely humanoid whirlwind of unusually dense air. Its constant spin is almost hypnotic, though it radiates a palpable disdain for all solid life.", spells = { "Hand of Tonis", "Slow", "Wind blast" }, abilities = { "call_wind", "tremors", "elemental_barrier_430", "elemental_bias_508", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_targeting_425" } },
    { template_id = "huge_earth_elemental", base_template = "huge_air_elemental", name = "huge earth elemental", level = 95, spawn_areas = { "Elemental Confluence" }, roam_areas = { "Elemental Confluence" }, family = "elemental", classification = "extra_planar", body_type = "hybrid", ds_bolt = 284, td = 410, armor_asg = 20, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "Massive and thick, with broad shoulders but no apparent head, the earth elemental appears to be a composite of the earth itself. A large, craggy maw in the middle of the elemental's chest appears to be the creature's mouth, and the earth elemental's huge feet and giant-sized fists look like they would pulverize flesh without much effort at all.", attacks = { { type = "pound" } }, spells = { "Hurl Boulder" }, abilities = { "tremors", "elemental_barrier_430", "elemental_bias_508", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_targeting_425" } },
    { template_id = "huge_ice_elemental", base_template = "water_elemental", name = "huge ice elemental", level = 95, spawn_areas = { "Elemental Confluence" }, roam_areas = { "Elemental Confluence" }, family = "elemental", classification = "extra_planar", body_type = "hybrid", ds_bolt = 315, td = 485, armor_asg = 10, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "The ice elemental is an amorphous conglomeration of ice and snow that writhes and moves about with a mind of its own. The intense cold generated by the ice elemental is nearly unbearable.", attacks = { { type = "pound" } }, abilities = { "cold_flare", "elemental_barrier_430", "elemental_bias_508", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_targeting_425" } },
    { template_id = "huge_water_elemental", base_template = "huge_air_elemental", name = "huge water elemental", level = 95, spawn_areas = { "Elemental Confluence" }, roam_areas = { "Elemental Confluence" }, family = "elemental", classification = "extra_planar", body_type = "hybrid", ds_bolt = 356, td = 400, armor_asg = 10, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "The water elemental's upper body is that of a humanoid, while its lower body forms a turbulent, watery vortex. The facial features of the elemental creature are vague and shifting, rippling with every contortion of its face. Sloshing and splashing noises accompany each movement of the water elemental, along with an odd gurgling.", attacks = { { type = "pound" } }, spells = { "Mystic Impedance" }, abilities = { "water_bolt", "elemental_barrier_430", "elemental_bias_508", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_targeting_425" } },

    -- Level 96
    { template_id = "greater_construct", name = "greater construct", level = 96, spawn_areas = { "Old Ta'Faendryl" }, roam_areas = { "Old Ta'Faendryl" }, family = "golem", classification = "magical", body_type = "biped", hp = 500, hp_variance = 50, ds_ranged = 344, td = 398, armor_asg = 20, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "The white granite-like features of the greater construct hold no hints of the giant creature's intentions or motivations. Its alabaster skin made more of the hardest rock than any living tissue makes the construct a formidable opponent for any who dare to trifle with it. Massing more than ten giantmen, it is a mountain of rock when in motion and very little, man or animal can oppose its desired path of travel once it is in motion.", attacks = { { type = "stomp" }, { type = "arm" } } },
    { template_id = "ithzir_adept", name = "ithzir adept", level = 96, spawn_areas = { "Old Ta'Faendryl" }, roam_areas = { "Old Ta'Faendryl" }, family = "ithzir", classification = "extra_planar", body_type = "biped", hp = 240, hp_variance = 24, ds_melee = 418, ds_ranged = 413, ds_bolt = 421, td = 425, armor_asg = 6, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "The Ithzir adept carries a bearing of absolute confidence, his piercing, pupil-less green eyes shrewdly taking in his surroundings. The Ithzir adept is slightly taller than a human, and while his humanoid form is similar to scores of other races, the hairless, blue-skinned body is nonetheless alien in its appearance. The adept wears a crisply-cut, silvery-blue tunic with high shoulders and a deep vee-neck. Emblazoned on the right breast of the tunic is a single green eye.", attacks = { { type = "quarterstaff" } }, spells = { "Weapon Fire" }, abilities = { "call_wind", "cold_flare", "fire_bolt", "shock_burst", "acid_spray", "water_bolt", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_barrier_430", "prismatic_guard_905", "mass_blur_911" } },
    { template_id = "lithe_veiled_sentinel", name = "lithe veiled sentinel", level = 96, spawn_areas = { "Sanctum" }, roam_areas = { "Sanctum" }, family = "humanoid", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 338, ds_ranged = 364, ds_bolt = 331, td = 403, armor_asg = 20, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "Blessed with an improbably lithe physique and muscles like corded iron, a lithe veiled sentinel is a short female with a face deeply darkened and lined by the sun's ungentle kiss. Her eyes are constantly, warily moving, and with every darting motion, they flash with a sharp-edged lambency like the glint of moonlight off of a shard of blue-green glass. The woman wears her shirt open to the waist, but is swathed in a shroud of green silk that flows in a rippling current on the air behind her. She is deadly grace embodied.", attacks = { { type = "kick" } }, spells = { "Thought Lash", "Force Projection", "Powersink" }, abilities = { "spirit_strike", "taunt", "charge_knockdown", "iron_skin_1202", "spirit_warding_i_101", "bravery_211", "strength_509" }, immune = { "stun" } },
    { template_id = "sidewinder", name = "sidewinder", level = 96, spawn_areas = { "Sanctum" }, roam_areas = { "Sanctum" }, family = "reptilian", body_type = "ophidian", hp = 400, hp_variance = 40, td = 411, armor_asg = 1, armor_natural = false, preferred_stance = "offensive", stance_profile = "skirmisher", description = "The swiftly writhing coils and flared, triangular head tells one all they need to know about the sidewinder: it is fast, and it is deadly. Scales as white as ivory flakes proceed in a sinuous pattern down the sidewinder's back, the muscles beneath undulating from side to side to propel it forward.", attacks = { { type = "bite" } } },
    { template_id = "siren", base_template = "mistydeep_siren", name = "siren", level = 96, spawn_areas = { "Ruined Temple" }, roam_areas = { "Ruined Temple" }, family = "fey", body_type = "hybrid", ds_melee = 429, ds_bolt = 453, td = 435, armor_asg = 1, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "The 'siren' is a peculiar vision of beauty from the sea. Though her lower body is that of an iridescently scaled fish, it takes away nothing from the rest of her ravishingly feminine figure draped in long, golden blonde hair and surrounded by a mystical aura. Discretely hidden webbing beneath her arms that aids in navigating deep waters has given rise to the erroneous legend that the siren can also fly. The soothing song from these strangely beautiful creatures has pulled many sailors to their deaths, and every moment that the siren gazes at you with her captivating brilliant blue eyes and serenades you with liquid notes from her glistening full lips is a moment that you plunge deeper into danger yourself.", attacks = { { type = "ensnare" } }, spells = { "Corrupt Essence", "Holding Song", "Lullabye", "Song of Depression", "Song of Unravelling" }, abilities = { "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414" } },
    { template_id = "triton_assassin", name = "triton assassin", level = 96, spawn_areas = { "Atoll" }, roam_areas = { "Atoll" }, family = "triton", body_type = "biped", hp = 300, hp_variance = 30, td = 441, udf = 510, armor_asg = 8, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "Dressed in grey-on-black, a triton assassin watches the area intently. The assassin bares her sharply serrated teeth, and her thick tail twitches silently with each breath. Inked upon one muscular forearm is a broken ivory trident overlaying a series of spiky runes.", attacks = { { type = "longsword" }, { type = "main_gauche" } } },
    { template_id = "triton_executioner", base_template = "ogre_warrior", name = "triton executioner", level = 96, spawn_areas = { "Ruined Temple" }, roam_areas = { "Ruined Temple" }, family = "triton", body_type = "biped", ds_melee = 331, td = 393, preferred_stance = "guarded", stance_profile = "ranged", description = "The triton executioner scans his surroundings with merciless eyes as if seeking his next client. Heavy, leathery lips are pulled into a perpetually disgusted sneer, pinching the creature's nostrils into narrow slits. Animal muscles, powerfully knotted beneath his moist blue-green skin, seem ready to spring in any direction. The executioner wears a dark blue tabard emblazoned with a silver wave upon the chest.", attacks = { { type = "handaxe" }, { type = "heavy_crossbow" }, { type = "longsword" } }, abilities = { "trip" } },

    -- Level 97
    { template_id = "fallen_crusader", base_template = "lost_soul", name = "fallen crusader", level = 97, spawn_areas = { "The Rift" }, roam_areas = { "The Rift" }, family = "ghost", classification = "non_corporeal_undead", body_type = "biped", hp = 300, hp_variance = 30, td = 392, armor_asg = 16, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "Roiling wisps of ethereal green mist fill in the form of a muscled warrior. Fleshy tones, segments of armor, and humanoid features flicker across her visage, as if the mist was remembering bits and pieces of the paladin's former body, if for only moments at a time. Unable to hold corporeal form, the only meaningful remnants of the crusader's prior existence are her stark conviction, held now in eyes which are no more than swirling grey voids, and her martial prowess.", abilities = { "spirit_warding_i_101", "spirit_defense_103", "lesser_shroud_120", "mantle_of_faith_1601" } },
    { template_id = "ithzir_seer", base_template = "grutik_shaman", name = "ithzir seer", level = 97, spawn_areas = { "Old Ta'Faendryl" }, roam_areas = { "Old Ta'Faendryl" }, family = "ithzir", classification = "extra_planar", body_type = "biped", ds_ranged = 279, ds_bolt = 386, td = 431, armor_asg = 6, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "The 'Ithzir seer' carries an authoritative bearing, her arresting, pupil-less green eyes taking in her surroundings with both confidence and cunning. Even when battle rages around her, each movement of the seer seems eerily effortless and calm. The Ithzir seer is slightly taller than a human, and while her humanoid form is similar to scores of other races, the hairless, blue-skinned body is nonetheless alien in its appearance. The seer wears a crisply-cut, silvery-blue tunic with high shoulders and a deep vee-neck. Emblazoned on the right breast of the tunic is a twelve-pointed golden star.", attacks = { { type = "quarterstaff" } }, spells = { "Telekinesis", "Bone Shatter", "Frenzy", "Mass Interference", "Silence", "Torment", "Spiritual Abolition", "Elemental Focus" }, abilities = { "flame_aura", "web_immobilize", "spirit_strike", "bravery_211", "self_control_613", "wall_of_force_140", "spirit_warding_i_101", "spirit_defense_103", "spirit_shield_202", "spell_shield_219" } },
    { template_id = "patchwork_flesh_monstrosity", name = "patchwork flesh monstrosity", level = 97, spawn_areas = { "Sanctum" }, roam_areas = { "Sanctum" }, family = "chimeric", classification = "corporeal_undead", body_type = "biped", hp = 550, hp_variance = 55, ds_melee = 263, td = 448, armor_asg = 5, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "A patchwork flesh monstrosity is near as tall as a giant and twice as broad, a lumbering monstrosity cobbled together from spare parts in tactless parody of a human form. Red-tinged serum leaks constantly from the straining stitches that maintain the monster's integrity. Only the barest glimmer of intelligence lurks in the monstrosity's eyes, and that, perhaps, is a blessing: anything with even half of a brain would be horrified to be such an abominable figure. From the looks of it, the monstrosity's has barely a quarter of one.", attacks = { { type = "ensnare_attack_ensnare" }, { type = "stomp_attack_stomp" } }, abilities = { "tackle" } },
    { template_id = "shambling_lurk", name = "shambling lurk", level = 97, spawn_areas = { "Sanctum" }, roam_areas = { "Sanctum" }, family = "zombie", classification = "corporeal_undead", body_type = "biped", hp = 550, hp_variance = 55, ds_melee = 350, ds_ranged = 377, td = 465, armor_asg = 1, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "Not dead so long that its body has begun to lose the unwinnable war against decay, a shambling lurk is firmly in the grip of rigor mortis. Its face is paralyzed in a slack-jawed smile that reveals broken teeth and a dry and swollen tongue. From the viridian firelight dancing in its eyes, it is clear that it is beyond the services of a cleric, except perhaps to grant the blessing of a swift release.", attacks = { { type = "bite" }, { type = "bite" } }, abilities = { "web_immobilize", "tremors" } },

    -- Level 98
    { template_id = "deathsworn_fanatic", name = "deathsworn fanatic", level = 98, spawn_areas = { "Sanctum" }, roam_areas = { "Sanctum" }, family = "humanoid", body_type = "biped", hp = 280, hp_variance = 28, ds_melee = 468, ds_ranged = 441, td = 405, armor_asg = 1, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "Clad in emerald robes of lush velvet that are stitched with tiny scales of clacking bronze, the fanatic is nearly fleshless, his reserves of fat and muscle burned away by a long war with madness. He has, judging from the stink of body odor and filth about him, not washed in weeks, and his gaze is as inconstant as the quickfire succession of random emotions that play across his tanned face.", spells = { "Finger (Pestilence?)", "Corrupt Essence", "Dark Catalyst" }, abilities = { "fire_bolt", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "spirit_shield_202", "spirit_warding_i_101", "elemental_targeting_425", "elemental_barrier_430" } },
    { template_id = "spectral_triton_defender", base_template = "shadowy_spectre", name = "spectral triton defender", level = 98, spawn_areas = { "Ruined Temple" }, roam_areas = { "Ruined Temple" }, family = "triton", classification = "non_corporeal_undead", body_type = "biped", preferred_stance = "guarded", stance_profile = "caster", description = "The triton defender forges ahead on powerful legs, as if unaware of their lack of substance, while thick and ropey muscles bunch powerfully along her oddly translucent arms. The skin covering her squat ethereal frame is the color of bleached, dirty leather and seems to retain the clammy wetness of living amphibians. Sweeping behind her muscled limbs, a long tail floats after the creature like a recently abandoned child." },
    { template_id = "spectral_triton_protector", name = "spectral triton protector", level = 98, spawn_areas = { "Atoll" }, roam_areas = { "Atoll" }, family = "triton", classification = "non_corporeal_undead", body_type = "biped", hp = 300, hp_variance = 30, td = 437, armor_asg = 20, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "Coral-spiked pauldrons are draped across a spectral triton protector's shoulders, the leather straps taut across her bare chest, the hide cutting into her tattooed blue-green flesh. Thick rings of ivory encircle her forearms and calves, etched in crude runes caked with blackish mud. Uneven streaks of pigment decorate her sunken cheekbones, the remnants splattered across her trident-inked collarbones.", attacks = { { type = "ball_and_chain" } } },
    { template_id = "triton_brawler", name = "triton brawler", level = 98, spawn_areas = { "Atoll" }, roam_areas = { "Atoll" }, family = "triton", body_type = "biped", hp = 300, hp_variance = 30, td = 435, armor_asg = 11, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "Wearing only a linen and leather pteruges, a triton brawler is covered in roughly inked black tattoos, a cavalcade of runes, sigils, and symbols twining about one another and obscuring his grey-blue flesh. Across his amphibian-like head is a tattoo of a powerful tentacle crushing a trident in its suckered grip. The brawler's eyes dart warily this way and that, and his tongue flicks in and out with deceptive laziness.", attacks = { { type = "ucs" } }, abilities = { "powerful_blow", "iron_skin_1202", "war_hardened" } },
    { template_id = "triton_combatant", base_template = "ogre_warrior", name = "triton combatant", level = 98, spawn_areas = { "Ruined Temple" }, roam_areas = { "Ruined Temple" }, family = "triton", body_type = "biped", td = 390, armor_asg = 20, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "The triton combatant stands hunched, her head thrust forward, and neck enveloped by heavy, muscled shoulders. Tiny alien eyes stare from a prominently bony brow, regarding the world with stubborn truculence. A mottled brown ridge rises from the amphibian's forehead and sweeps up and back, hugging her skull. This heavy protuberance, covered with damp, leathery skin, provides her with formidable head and neck protection.", attacks = { { type = "claw" }, { type = "trident" } }, abilities = { "charge_knockdown", "disarm_weapon", "taunt", "tackle" } },

    -- Level 99
    { template_id = "huge_fire_elemental", base_template = "huge_ice_elemental", name = "huge fire elemental", level = 99, spawn_areas = { "Elemental Confluence" }, roam_areas = { "Elemental Confluence" }, family = "elemental", classification = "extra_planar", body_type = "hybrid", ds_bolt = 307, td = 428, armor_asg = 10, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "The fire elemental is a massing of flames that flow and flicker with a life of their own. The intense heat generated by the fire elemental is nearly unbearable.", attacks = { { type = "claw" } }, abilities = { "fire_bolt", "elemental_barrier_430", "elemental_bias_508", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_targeting_425" } },
    { template_id = "huge_steam_elemental", base_template = "huge_air_elemental", name = "huge steam elemental", level = 99, spawn_areas = { "Elemental Confluence" }, roam_areas = { "Elemental Confluence" }, family = "elemental", classification = "extra_planar", body_type = "hybrid", ds_bolt = 280, td = 428, armor_asg = 10, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "The steam elemental is a dense cloud of solid steam, occasionally manifesting a mouth or tendrils with which to affect its surroundings. It constantly expands and contracts, but never loses its unbearably hot aura.", attacks = { { type = "ensnare" } }, spells = { "Minor Steam" }, abilities = { "earthen_fury_caster", "elemental_barrier_430", "elemental_bias_508", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_targeting_425" } },

    -- Level 100
    { template_id = "glistening_cerebralite", base_template = "huge_steam_elemental", name = "glistening cerebralite", level = 100, spawn_areas = { "The Rift" }, roam_areas = { "The Rift" }, family = "cerebralite", classification = "extra_planar", body_type = "hybrid", hp = 400, hp_variance = 40, ds_bolt = 338, td = 455, armor_asg = 12, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "A grey-splotched pink, the glistening cerebralite is a fleshy mass that somewhat resembles a humanoid brain, though it is oversized and grossly proportioned. Eye-stalks sprout from either hemisphere, supporting a pair of lidless eyes with iridescent irises and ebony pupils. Thick veins span the wrinkled surface of the creature's body, pulsing rhythmically with a writhing mass of barbed tentacles sprouting from its underside. A viscous fluid coats the cerebralite's surface, the substance phlegm-like in consistency.", spells = { "Balefire", "Empathic Assault", "Cloak of Shadows", "Sympathy", "Song of Depression", "Spiritual Abolition" }, abilities = { "shock_burst", "heroism_215", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "spirit_shield_202" } },
    { template_id = "huge_lava_elemental", base_template = "huge_fire_elemental", name = "huge lava elemental", level = 100, spawn_areas = { "Elemental Confluence" }, roam_areas = { "Elemental Confluence" }, family = "elemental", classification = "extra_planar", body_type = "hybrid", ds_bolt = 335, td = 428, armor_asg = 10, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "The lava elemental is a bubbling mound of lava, across which an occasional warped face appears before dissolving away. Various appendages form and melt away constantly, as the alien creature goes about its business.", attacks = { { type = "pound_double_attack" } }, abilities = { "fire_bolt", "elemental_barrier_430", "elemental_bias_508", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_targeting_425" } },
    { template_id = "huge_lightning_elemental", base_template = "huge_steam_elemental", name = "huge lightning elemental", level = 100, spawn_areas = { "Elemental Confluence" }, roam_areas = { "Elemental Confluence" }, family = "elemental", classification = "extra_planar", body_type = "hybrid", ds_bolt = 331, td = 431, armor_asg = 10, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "The lightning elemental is a crackling mass of solidified power, definitely alien to Elanthia. Nearly gelatinous in substance, solid bolts of lightning weave themselves into the skeletal form of some horrible beast, only to arc in an instant to a vaguely humanoid form and then back again.", attacks = { { type = "charge" } }, spells = { "Elemental Strike", "Mind Jolt" }, abilities = { "shock_burst", "call_wind", "elemental_barrier_430", "elemental_bias_508", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_targeting_425" } },
    { template_id = "triton_fanatic", name = "triton fanatic", level = 100, spawn_areas = { "Atoll" }, roam_areas = { "Atoll" }, family = "triton", body_type = "biped", hp = 300, hp_variance = 30, td = 468, armor_asg = 17, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "A triton fanatic visibly twitches as he clutches a contorted driftwood fetish within his sigil-gouged fingers, his crazed bloodshot eyes darting to and fro beneath a shredded miter of dark oilskin. The last vestiges of a hair-sewn tunic barely cling to his emaciated form, stained in rust-colored splotches from collar to knee, and lashed together with knots of thick sinew. Branded across his forehead is the image of a broken trident, the forks splayed between his brows.", attacks = { { type = "hammer_of_kai" } }, spells = { "Pious Trial", "Repentance", "Arm of the Arkati", "Zealot", "Fervor" }, abilities = { "spirit_strike", "taunt", "mantle_of_faith_1601" } },
    { template_id = "triton_radical", base_template = "ogre_warrior", name = "triton radical", level = 100, spawn_areas = { "Ruined Temple" }, roam_areas = { "Ruined Temple" }, family = "triton", body_type = "biped", ds_melee = 407, ds_bolt = 326, td = 453, armor_asg = 12, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "Glaring angrily and gnashing his sharp yellowed teeth, the triton radical stalks along muttering to himself as if involved in angry debate with a phantasmal antagonist. Pale, red-rimmed eyes sit deep in a heavy-boned skull, which perches upon a long, slender neck. The radical's body pitches forward alarmingly, so only the weight of his tail prevents a return to a four-legged posture. Upon his tapered brow is set a golden crown bearing a large, wave-etched crystal drop.", attacks = { { type = "scaling_fork" }, { type = "trident" } }, spells = { "Censure", "Divine Strike", "Divine Wrath", "Frenzy", "Judgment" }, abilities = { "heroism_215", "spirit_strike", "charge_knockdown", "lesser_shroud_120", "mantle_of_faith_1601" } },
    { template_id = "war_griffin", name = "war griffin", level = 100, spawn_areas = { "Old Ta'Faendryl" }, roam_areas = { "Old Ta'Faendryl" }, family = "griffin", body_type = "hybrid", hp = 400, hp_variance = 40, ds_melee = 343, ds_bolt = 347, td = 439, armor_asg = 12, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "The war griffin is a magnificent beast, as if designed by the gods to embody fierce and graceful predation. Its front legs, forebody, wings, and head are those of a great eagle, complete with large golden feathers and aquiline beak. The rear half of the creature's body is that of a powerful lion, with short white fur and a long feline tail. Trained by its captors to enhance its fighting prowess, the massive war griffin is poetry in motion, its beautiful ferocity the last sight its foes ever see.", attacks = { { type = "bite" }, { type = "claw" }, { type = "impale" } }, abilities = { "sonic_wail" } },
}

